import Foundation
import CryptoKit
import Security

// Cryptographic core of the v3 wire protocol.
//
// TCP runs TLS 1.3 with external PSKs: a bootstrap PSK derived from an
// 8-digit PIN plus a per-connection salt, or a 256-bit random pairing key
// persisted in the Keychain after first approval (see ERDIdentity).
// UDP datagrams are sealed with AES-256-GCM under direction-separated keys
// derived from the pairing key and a per-session salt.
//
// HKDF is implemented locally because CryptoKit's HKDF API requires macOS 14
// while EclipticRD targets macOS 13.

/// RFC 5869 HKDF-SHA256 (Extract/Expand); test vectors live in the XCTest target.
enum HKDF {
    static func extract(salt: Data, ikm: Data) -> Data {
        let key = SymmetricKey(data: salt.isEmpty ? Data(repeating: 0, count: 32) : salt)
        return Data(HMAC<SHA256>.authenticationCode(for: ikm, using: key))
    }

    static func expand(prk: Data, info: Data, length: Int) -> Data {
        precondition(length >= 0 && length <= 255 * 32, "HKDF-Expand length out of range")
        var okm = Data()
        var t = Data()
        var counter: UInt8 = 1
        while okm.count < length {
            var input = t
            input.append(info)
            input.append(counter)
            t = Data(HMAC<SHA256>.authenticationCode(for: input, using: SymmetricKey(data: prk)))
            okm.append(t)
            counter &+= 1
        }
        return okm.prefix(length)
    }

    static func derive(ikm: Data, salt: Data, info: Data, length: Int = 32) -> Data {
        expand(prk: extract(salt: salt, ikm: ikm), info: info, length: length)
    }
}

/// AES-256-GCM cipher for UDP datagrams with sliding-window replay protection.
///
/// Datagram wire format: `[12-byte nonce][ciphertext][16-byte tag]`
/// Nonce layout: `[4-byte session prefix][8-byte big-endian packet counter]`.
/// Prefix and traffic key are direction-separated, so nonce reuse across the
/// two directions is impossible even under counter resets.
public final class DatagramCipher: @unchecked Sendable {
    public static let nonceSize = 12
    public static let tagSize = 16
    public static let windowSize: UInt64 = 4096

    private let key: SymmetricKey
    private let noncePrefix: [UInt8] // 4 bytes, derived per direction per session
    private let lock = NSLock()
    private var sendCounter: UInt64 = 0
    private var highestReceived: UInt64 = 0
    private var receivedBlocks: [UInt64: UInt64] = [:] // block index -> 64-bit seen mask

    init(key: Data, noncePrefix: Data) {
        precondition(key.count == 32, "DatagramCipher expects a 256-bit key")
        precondition(noncePrefix.count == 4, "DatagramCipher expects a 4-byte nonce prefix")
        self.key = SymmetricKey(data: key)
        self.noncePrefix = [UInt8](noncePrefix)
    }

    /// Derive the per-direction UDP traffic cipher from the pairing master key
    /// and the session salt exchanged inside the authenticated handshake.
    public static func udpCipher(masterKey: Data, sessionSalt: Data, clientToHost: Bool) -> DatagramCipher {
        let ikm = HKDF.derive(ikm: masterKey, salt: sessionSalt, info: Data("erd/udp-ikm/v3".utf8))
        let info = Data(clientToHost ? "erd/udp-c2h/v3".utf8 : "erd/udp-h2c/v3".utf8)
        let key = HKDF.derive(ikm: ikm, salt: sessionSalt, info: info, length: 32)
        let prefix = HKDF.derive(ikm: ikm, salt: sessionSalt, info: info + Data("/nonce".utf8), length: 4)
        return DatagramCipher(key: key, noncePrefix: prefix)
    }

    /// Encrypt `plaintext`; returns nonce||ciphertext||tag, or nil on internal failure.
    public func seal(_ plaintext: Data, aad: Data = Data()) -> Data? {
        lock.lock()
        sendCounter &+= 1
        let counter = sendCounter
        lock.unlock()

        var nonceBytes = noncePrefix
        var bigCounter = counter.bigEndian
        withUnsafeBytes(of: &bigCounter) { nonceBytes.append(contentsOf: $0) }
        guard let nonce = try? AES.GCM.Nonce(data: Data(nonceBytes)),
              let box = try? AES.GCM.seal(plaintext, using: key, nonce: nonce, authenticating: aad)
        else { return nil }
        return Data(nonceBytes) + box.ciphertext + box.tag
    }

    /// Decrypt a datagram produced by `seal`. Returns nil for tampered,
    /// duplicated, or too-old packets. Thread-safe.
    public func open(_ datagram: Data, aad: Data = Data()) -> Data? {
        guard datagram.count > Self.nonceSize + Self.tagSize else { return nil }
        let nonceData = datagram.subdata(in: 0..<Self.nonceSize)
        let counter = nonceData.subdata(in: 4..<12).withUnsafeBytes { $0.load(as: UInt64.self).bigEndian }
        let ciphertext = datagram.subdata(in: Self.nonceSize..<(datagram.count - Self.tagSize))
        let tag = datagram.subdata(in: (datagram.count - Self.tagSize)..<datagram.count)

        lock.lock(); defer { lock.unlock() }

        // Replay window fast reject.
        guard counter + Self.windowSize > highestReceived else { return nil }
        let block = counter / 64
        let mask: UInt64 = 1 << (counter % 64)
        if (receivedBlocks[block] ?? 0) & mask != 0 { return nil }

        guard let nonce = try? AES.GCM.Nonce(data: nonceData),
              let box = try? AES.GCM.SealedBox(nonce: nonce, ciphertext: ciphertext, tag: tag),
              let plaintext = try? AES.GCM.open(box, using: key, authenticating: aad)
        else { return nil }

        receivedBlocks[block, default: 0] |= mask
        if counter > highestReceived { highestReceived = counter }
        let cutoff = highestReceived >= Self.windowSize ? (highestReceived - Self.windowSize) / 64 : 0
        if receivedBlocks.count > 128 {
            receivedBlocks = receivedBlocks.filter { $0.key >= cutoff }
        }
        return plaintext
    }
}

/// Shared helpers for the identity material backing the TLS-PSK channels.
public enum ERDCrypto {
    /// TLS-PSK for a bootstrap (first-time pairing) connection. The host
    /// rotates the PIN per pairing session, so each session gets a fresh key
    /// without per-connection salt negotiation.
    public static func bootstrapPSK(pin: String) -> Data {
        HKDF.derive(ikm: Data(pin.utf8),
                    salt: Data("erd/bootstrap/v3".utf8),
                    info: Data("erd/tls-psk".utf8))
    }

    /// PSK for a paired device: the raw 256-bit Keychain pairing key.
    public static func pairingPSK(_ key: Data) -> Data { key }

    /// Uniform 32-byte random key material.
    public static func randomKey() -> Data {
        var key = Data(count: 32)
        let status = key.withUnsafeMutableBytes {
            SecRandomCopyBytes(kSecRandomDefault, 32, $0.baseAddress!)
        }
        precondition(status == errSecSuccess, "SecRandomCopyBytes failed: \(status)")
        return key
    }

    /// 8-digit zero-padded bootstrap PIN from the system RNG.
    public static func randomPIN(digits: Int = ERDConstants.pinLength) -> String {
        var value: UInt64 = 0
        let bound = UInt64(1) << (6 * digits) // keep modulo bias negligible
        repeat {
            let status = withUnsafeMutableBytes(of: &value) {
                SecRandomCopyBytes(kSecRandomDefault, 8, $0.baseAddress!)
            }
            precondition(status == errSecSuccess, "SecRandomCopyBytes failed: \(status)")
        } while value >= UInt64.max - (UInt64.max % bound)
        let modulus = UInt64(pow(10.0, Double(digits)))
        return String(format: "%0\(digits)d", value % modulus)
    }
}

import Foundation
import Security

// Pairing identity, Keychain storage, and bootstrap PIN state.
//
// First contact: the client offers TLS-PSK identity "erd-b1.<salt>", whose
// key derives from the host's 8-digit bootstrap PIN. The host approves the
// device with an explicit prompt before any input or screen access is
// granted, and repeated PIN failures lock the bootstrap path globally.
// On approval the host generates a 256-bit pairing key and hands it to the
// client over the encrypted channel; both sides persist it in the Keychain.
// Later sessions use identity "erd-p1.<uuid>" with that key, which cannot
// be brute-forced offline the way the PIN can.
//
// Residual risk: an attacker who records the bootstrap handshake and cracks
// the PIN offline recovers that one session and the pairing key. Consent,
// lockout, and PIN expiry mitigate this; SPAKE2+ is the follow-up once a
// vetted Swift PAKE implementation is available.

/// A persisted trust relationship with one remote device.
public struct PairingRecord: Codable, Equatable, Identifiable, Sendable {
    public let id: String
    public var name: String
    public let key: Data
    public let addedAt: Date

    public init(id: String = UUID().uuidString, name: String, key: Data, addedAt: Date = Date()) {
        self.id = id
        self.name = name
        self.key = key
        self.addedAt = addedAt
    }

    public var pskIdentity: String { "erd-p1.\(id)" }
}

/// Keychain-backed storage for pairing records.
public enum PairingStore {
    private static let service = "eclipticrd.pairing.v1"

    public static func loadAll() -> [PairingRecord] {
        var query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecReturnAttributes as String: true,
            kSecMatchLimit as String: kSecMatchLimitAll,
        ]
        var items: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &items) == errSecSuccess,
              let entries = items as? [[String: Any]] else { return [] }
        return entries.compactMap { entry in
            guard let account = entry[kSecAttrAccount as String] as? String else { return nil }
            return load(id: account)
        }
    }

    public static func load(id: String) -> PairingRecord? {
        var query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: id,
            kSecReturnData as String: true,
        ]
        var item: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &item) == errSecSuccess,
              let data = item as? Data,
              let record = try? JSONDecoder().decode(PairingRecord.self, from: data)
        else { return nil }
        return record
    }

    @discardableResult
    public static func save(_ record: PairingRecord) -> Bool {
        guard let data = try? JSONEncoder().encode(record) else { return false }
        let base: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: record.id,
        ]
        let add = base.merging([kSecValueData as String: data,
                                kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlock]) { _, new in new }
        let status = SecItemAdd(add as CFDictionary, nil)
        if status == errSecDuplicateItem {
            let update = [kSecValueData as String: data] as CFDictionary
            return SecItemUpdate(base as CFDictionary, update) == errSecSuccess
        }
        return status == errSecSuccess
    }

    @discardableResult
    public static func delete(id: String) -> Bool {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: id,
        ]
        let status = SecItemDelete(query as CFDictionary)
        return status == errSecSuccess || status == errSecItemNotFound
    }
}

/// One TLS pre-shared key entry offered on a channel.
public struct ERDPSK: Equatable, Sendable {
    public let identity: String
    public let key: Data

    public init(identity: String, key: Data) {
        self.identity = identity
        self.key = key
    }
}

/// Host-side pairing authority: pending bootstrap PIN state, failure lockout,
/// and the set of PSKs the TCP listener should accept.
public final class PairingManager: @unchecked Sendable {
    public static let shared = PairingManager()

    private struct PendingPairing {
        let pin: String
        let expiresAt: Date
    }

    private let lock = NSLock()
    private var pending: PendingPairing?
    private var failureCount = 0
    private var failureWindowStart = Date.distantPast
    private var bootstrapLockedUntil = Date.distantPast

    // MARK: - Bootstrap PIN lifecycle (host)

    /// Start accepting bootstrap connections; returns the PIN to display.
    /// An explicit numeric PIN of the configured length (internet mode, where
    /// both sides type the same code) overrides the generated one.
    @discardableResult
    public func beginPairing(explicitPIN: String? = nil) -> String {
        var pin = ERDCrypto.randomPIN()
        if let explicitPIN, explicitPIN.count == ERDConstants.pinLength,
           explicitPIN.allSatisfy({ $0.isNumber }) {
            pin = explicitPIN
        }
        let pending = PendingPairing(pin: pin,
                                     expiresAt: Date().addingTimeInterval(ERDConstants.pairingPINExpiry))
        lock.lock()
        self.pending = pending
        failureCount = 0
        bootstrapLockedUntil = .distantPast
        lock.unlock()
        return pin
    }

    public func cancelPairing() {
        lock.lock()
        pending = nil
        lock.unlock()
    }

    public var isPairingActive: Bool {
        lock.withLock { pending != nil && pending!.expiresAt > Date() }
    }

    /// All PSKs the host listener should accept: every paired device plus the
    /// pending bootstrap entry while pairing is active and not locked out.
    public func hostPSKs() -> [ERDPSK] {
        lock.lock(); defer { lock.unlock() }
        var psks = PairingStore.loadAll().map { ERDPSK(identity: $0.pskIdentity, key: ERDCrypto.pairingPSK($0.key)) }
        if let pending, pending.expiresAt > Date(), Date() >= bootstrapLockedUntil {
            psks.append(ERDPSK(identity: Self.bootstrapIdentity,
                               key: ERDCrypto.bootstrapPSK(pin: pending.pin)))
        }
        return psks
    }

    /// Resolve one offered identity to its PSK (used by the TLS verify hook).
    public func resolvePSK(identity: String) -> ERDPSK? {
        hostPSKs().first { $0.identity == identity }
    }

    /// Record a failed bootstrap authentication. Returns true when bootstrap
    /// is now locked out.
    @discardableResult
    public func recordBootstrapFailure() -> Bool {
        lock.lock(); defer { lock.unlock() }
        let now = Date()
        if now.timeIntervalSince(failureWindowStart) > ERDConstants.pairingAttemptWindow {
            failureCount = 0
            failureWindowStart = now
        }
        failureCount += 1
        if failureCount >= ERDConstants.maxPairingAttempts {
            bootstrapLockedUntil = now.addingTimeInterval(ERDConstants.pairingLockout)
            pending = nil
            return true
        }
        return false
    }

    // MARK: - Grant / adopt (both sides)

    /// Host: mint + persist a pairing record for an approved bootstrap peer.
    public func grantPairing(hostname: String) -> PairingRecord {
        let record = PairingRecord(name: hostname, key: ERDCrypto.randomKey())
        PairingStore.save(record)
        return record
    }

    /// Client: persist a pairing record received from a host.
    public func adoptPairing(_ record: PairingRecord) {
        PairingStore.save(record)
    }

    public func pairedDevices() -> [PairingRecord] {
        PairingStore.loadAll().sorted { $0.addedAt > $1.addedAt }
    }

    public func revokePairing(id: String) {
        PairingStore.delete(id: id)
    }

    // MARK: - Client side

    public static let bootstrapIdentity = "erd-b1"

    /// The client connects either with a previously granted pairing key or,
    /// while pairing for the first time, with the bootstrap PSK for `pin`.
    public func clientPSK(pin: String) -> ERDPSK {
        ERDPSK(identity: Self.bootstrapIdentity, key: ERDCrypto.bootstrapPSK(pin: pin))
    }

    public func clientPSK(for record: PairingRecord) -> ERDPSK {
        ERDPSK(identity: record.pskIdentity, key: ERDCrypto.pairingPSK(record.key))
    }
}

private extension NSLock {
    func withLock<T>(_ body: () -> T) -> T {
        lock()
        defer { unlock() }
        return body()
    }
}

import Foundation

/// Client -> host: request device pairing. Sent over the PIN-protected
/// bootstrap TLS channel before any screen or input capability is granted.
public struct PairingRequestPayload {
    public let hostname: String

    public init(hostname: String) {
        self.hostname = hostname
    }

    public func serialize() -> Data {
        let nameData = Data(hostname.utf8).prefix(Int(UInt16.max))
        var d = Data(capacity: 2 + nameData.count)
        var nameLen = UInt16(nameData.count).littleEndian
        d.append(Data(bytes: &nameLen, count: 2))
        d.append(nameData)
        return d
    }

    public static func deserialize(from data: Data) -> PairingRequestPayload? {
        guard data.count >= 2 else { return nil }
        let nameLen = Int(data.subdata(in: 0..<2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard nameLen <= 1024, data.count >= 2 + nameLen else { return nil }
        let hostname = String(data: data.subdata(in: 2..<(2 + nameLen)), encoding: .utf8) ?? ""
        return PairingRequestPayload(hostname: hostname)
    }
}

/// Host -> client: the pairing grant. `key` is the 256-bit pairing key the
/// client must persist; `hostName` is the display name the client stores for
/// future connections.
public struct PairingGrantPayload {
    public let pairingID: String
    public let hostName: String
    public let key: Data

    public init(pairingID: String, hostName: String, key: Data) {
        self.pairingID = pairingID
        self.hostName = hostName
        self.key = key
    }

    public func serialize() -> Data {
        let idData = Data(pairingID.utf8).prefix(Int(UInt8.max))
        let nameData = Data(hostName.utf8).prefix(Int(UInt16.max))
        var d = Data(capacity: 2 + idData.count + 2 + nameData.count + 1 + key.count)
        var idLen = UInt8(idData.count); d.append(Data(bytes: &idLen, count: 1))
        d.append(idData)
        var nameLen = UInt16(nameData.count).littleEndian
        d.append(Data(bytes: &nameLen, count: 2))
        d.append(nameData)
        var keyLen = UInt8(key.count); d.append(Data(bytes: &keyLen, count: 1))
        d.append(key)
        return d
    }

    public static func deserialize(from data: Data) -> PairingGrantPayload? {
        guard data.count >= 1 else { return nil }
        let idLen = Int(data[0])
        var offset = 1
        guard data.count >= offset + idLen + 2 else { return nil }
        let pairingID = String(data: data.subdata(in: offset..<(offset + idLen)), encoding: .utf8) ?? ""
        offset += idLen
        let nameLen = Int(data.subdata(in: offset..<(offset + 2)).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        offset += 2
        guard data.count >= offset + nameLen + 1 else { return nil }
        let hostName = String(data: data.subdata(in: offset..<(offset + nameLen)), encoding: .utf8) ?? ""
        offset += nameLen
        let keyLen = Int(data[offset])
        offset += 1
        guard keyLen == 32, data.count >= offset + keyLen else { return nil }
        let key = data.subdata(in: offset..<(offset + keyLen))
        return PairingGrantPayload(pairingID: pairingID, hostName: hostName, key: key)
    }
}

public enum PairingRejectReason: UInt8 {
    case deniedByHost = 0
    case lockedOut = 1
    case pairingDisabled = 2
}

public struct PairingRejectPayload {
    public let reason: PairingRejectReason

    public init(reason: PairingRejectReason) {
        self.reason = reason
    }

    public func serialize() -> Data {
        var r = reason.rawValue
        return Data(bytes: &r, count: 1)
    }

    public static func deserialize(from data: Data) -> PairingRejectPayload? {
        guard data.count >= 1, let reason = PairingRejectReason(rawValue: data[0]) else { return nil }
        return PairingRejectPayload(reason: reason)
    }
}

import Foundation
import Network
import Security

/// Transport security selection for a TCP channel.
///
/// `.psk` upgrades the channel to TLS 1.3 with external pre-shared keys.
/// The host offers one PSK per paired device plus the pending bootstrap key
/// (see PairingManager.hostPSKs); the client offers exactly one. Identity
/// strings on the wire pick the key, so no certificates are involved.
public enum ChannelSecurity {
    case none
    case psk([ERDPSK])

    var tlsParameters: NWParameters? {
        guard case let .psk(psks) = self, !psks.isEmpty else { return nil }
        let options = NWProtocolTLS.Options()
        let sec = options.securityProtocolOptions
        for psk in psks {
            sec_protocol_options_add_pre_shared_key(sec,
                                                    Self.dispatchData(psk.key) as dispatch_data_t,
                                                    Self.dispatchData(Data(psk.identity.utf8)) as dispatch_data_t)
        }
        sec_protocol_options_set_min_tls_protocol_version(sec, .TLSv12)
        sec_protocol_options_set_max_tls_protocol_version(sec, .TLSv13)
        // PSK-only TLS 1.3 exchanges no certificate; the transcript MAC binds
        // both sides to the shared key, which is the authentication.
        sec_protocol_options_set_verify_block(sec, { _, _, complete in complete(true) }, DispatchQueue.global(qos: .userInitiated))
        return NWParameters(tls: options)
    }

    private static func dispatchData(_ data: Data) -> DispatchData {
        // DispatchData(bytes:) copies the buffer (default destructor), so the
        // result outlives the Data storage.
        data.withUnsafeBytes { DispatchData(bytes: $0) }
    }
}

public class TCPChannel {
    private var connection: NWConnection?
    private var listener: NWListener?
    private let queue = DispatchQueue(label: "eclipticrd.tcp", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var receiveBuffer = Data()
    private var timeoutWorkItem: DispatchWorkItem?
    private var didNotifyDisconnect = false
    public var security: ChannelSecurity
    private var listenPort: UInt16?

    public var onConnect: (@Sendable () -> Void)?
    public var onDisconnect: (@Sendable () -> Void)?
    public var onReceive: (@Sendable (Data) -> Void)?
    public private(set) var lastFailureDescription: String?
    public private(set) var connectionStateDescription: String?

    public var remoteHostIP: String? {
        guard let endpoint = connection?.currentPath?.remoteEndpoint else { return nil }
        if case .hostPort(let host, _) = endpoint { return "\(host)" }
        return nil
    }

    public init(security: ChannelSecurity = .none) {
        self.security = security
        queue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    private var connectionParameters: NWParameters {
        let params = security.tlsParameters ?? NWParameters.tcp
        // Pairing swaps PSKs by restarting the listener; without endpoint
        // reuse the immediate rebind loses the race with the old socket.
        params.allowLocalEndpointReuse = true
        return params
    }

    // MARK: - Server side

    public func startListening(port: UInt16) throws {
        listenPort = port
        listener = try NWListener(using: connectionParameters, on: NWEndpoint.Port(rawValue: port)!)
        listener?.newConnectionHandler = { [weak self] conn in
            self?.setupConnection(conn)
        }
        listener?.stateUpdateHandler = { state in
            ERDLog.network("[TCP] Listener state: \(state)")
        }
        listener?.start(queue: queue)
    }

    public func advertiseService(name: String) {
        listener?.service = NWListener.Service(name: name, type: ERDConstants.bonjourServiceType, domain: ERDConstants.bonjourDomain)
    }

    /// Swap the offered PSKs (e.g. after a pairing grant) and restart the
    /// listener once the old one has fully released its port.
    public func updateSecurity(_ newSecurity: ChannelSecurity) {
        queue.async { [weak self] in
            guard let self = self else { return }
            self.security = newSecurity
            guard let port = self.listenPort, let old = self.listener else { return }
            self.listener = nil
            old.stateUpdateHandler = { [weak self] state in
                if case .cancelled = state {
                    old.stateUpdateHandler = nil
                    try? self?.startListening(port: port)
                }
            }
            old.cancel()
        }
    }

    // MARK: - Client side

    public func connect(host: String, port: UInt16) {
        let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(host), port: NWEndpoint.Port(rawValue: port)!)
        connect(to: endpoint)
    }

    public func connect(to endpoint: NWEndpoint) {
        let conn = NWConnection(to: endpoint, using: connectionParameters)
        queue.async { [weak self] in
            self?.setupConnection(conn)
        }
        setTimeout(ERDConstants.connectionTimeout)
    }

    public func connectICE(endpoints: [NWEndpoint]) {
        for endpoint in endpoints {
            let conn = NWConnection(to: endpoint, using: connectionParameters)
            conn.stateUpdateHandler = { [weak self] state in
                guard let self = self else { return }
                switch state {
                case .ready:
                    if self.connection == nil {
                        self.connection = conn
                        self.didNotifyDisconnect = false
                        self.cancelTimeout()
                        ERDLog.network("[Client] ICE Won by \(endpoint)")
                        conn.stateUpdateHandler = { [weak self] state in
                            switch state {
                            case .ready:
                                break
                            case .failed(let err):
                                ERDLog.error("[TCP] ICE connection failed: \(err)")
                                self?.notifyDisconnect()
                            case .cancelled:
                                self?.notifyDisconnect()
                            default:
                                break
                            }
                        }
                        self.startReceiving()
                        self.onConnect?()
                    } else {
                        conn.cancel()
                    }
                case .failed, .cancelled:
                    break
                default: break
                }
            }
            conn.start(queue: queue)
        }
        setTimeout(ERDConstants.connectionTimeout)
    }

    public func setTimeout(_ seconds: Double) {
        queue.async { [weak self] in
            self?.cancelTimeout()
            let work = DispatchWorkItem { [weak self] in
                guard let self = self else { return }
                ERDLog.error("[TCP] Connection timeout after \(seconds)s")
                self.connection?.cancel()
                self.connection = nil
                self.notifyDisconnect()
            }
            self?.timeoutWorkItem = work
            self?.queue.asyncAfter(deadline: .now() + seconds, execute: work)
        }
    }

    // MARK: - Send

    public func send(_ data: Data) {
        // Length-prefixed framing: 4-byte little-endian length + payload
        var len = UInt32(data.count).littleEndian
        var frame = Data(bytes: &len, count: 4)
        frame.append(data)
        connection?.send(content: frame, completion: .contentProcessed { error in
            if let error = error {
                ERDLog.error("[TCP] Send error: \(error)")
            }
        })
    }

    public func sendControl(_ msg: ControlMessage) {
        let header = PacketHeader(type: .control, sequence: 0, timestamp: currentTimestamp())
        var packet = header.serialize()
        packet.append(msg.serialize())
        send(packet)
    }

    public func sendInput(_ input: InputEventPayload) {
        let header = PacketHeader(type: .inputEvent, sequence: 0, timestamp: currentTimestamp())
        var packet = header.serialize()
        packet.append(input.serialize())
        send(packet)
    }

    // MARK: - Stop

    public func stop() {
        let work = {
            self.cancelTimeout()
            self.connection?.cancel()
            self.connection = nil
            self.listener?.cancel()
            self.listener = nil
            self.receiveBuffer = Data()
            self.notifyDisconnect()
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    public func disconnectConnection() {
        let work = {
            self.cancelTimeout()
            self.connection?.cancel()
            self.connection = nil
            self.receiveBuffer = Data()
            self.notifyDisconnect()
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    // MARK: - Internal

    private func cancelTimeout() {
        timeoutWorkItem?.cancel()
        timeoutWorkItem = nil
    }

    private func setupConnection(_ conn: NWConnection) {
        connection = conn
        didNotifyDisconnect = false
        conn.stateUpdateHandler = { [weak self] state in
            self?.connectionStateDescription = "\(state)"
            switch state {
            case .ready:
                self?.cancelTimeout()
                ERDLog.network("[TCP] Connected to \(conn.endpoint)")
                self?.startReceiving()
                self?.onConnect?()
            case .failed(let err):
                ERDLog.error("[TCP] Connection failed: \(err)")
                if let self {
                    queue.async { self.lastFailureDescription = "\(err)" }
                }
                self?.notifyDisconnect()
            case .cancelled:
                self?.notifyDisconnect()
            default: break
            }
        }
        conn.start(queue: queue)
    }

    private func notifyDisconnect() {
        guard !didNotifyDisconnect else { return }
        didNotifyDisconnect = true
        onDisconnect?()
    }

    private func startReceiving() {
        connection?.receive(minimumIncompleteLength: 1, maximumLength: 262144) { [weak self] content, _, isComplete, error in
            guard let self = self else { return }
            if let data = content {
                self.receiveBuffer.append(data)
                self.processBuffer()
            }
            if let error = error {
                ERDLog.error("[TCP] Receive error: \(error)")
                self.notifyDisconnect()
                return
            }
            if !isComplete {
                self.startReceiving()
            } else {
                self.notifyDisconnect()
            }
        }
    }

    private func processBuffer() {
        while receiveBuffer.count >= 4 {
            let length = Int(receiveBuffer.prefix(4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
            guard length > 0, length <= 16_777_216 else {
                // Invalid length — drop buffer to recover
                ERDLog.error("[TCP] Invalid frame length: \(length), dropping buffer")
                receiveBuffer.removeAll()
                break
            }
            guard receiveBuffer.count >= 4 + length else {
                break
            }
            let payload = receiveBuffer.subdata(in: 4..<(4 + length))
            receiveBuffer.removeSubrange(0..<(4 + length))
            onReceive?(payload)
        }
    }

    private func currentTimestamp() -> UInt32 {
        UInt32(truncatingIfNeeded: UInt64(Date().timeIntervalSince1970 * 1000))
    }
}

import Foundation
import Network

public class UDPChannel {
    private var connection: NWConnection?
    private var listener: NWListener?
    private let queue = DispatchQueue(label: "eclipticrd.udp", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var sequenceCounter: UInt32 = 0
    private let seqLock = NSLock()
    private let cipherLock = NSLock()
    private var _sendCipher: DatagramCipher?
    private var _receiveCipher: DatagramCipher?
    private var isReceiving = false

    public var onReceive: (@Sendable (Data, NWEndpoint?) -> Void)?
    public var onReady: (@Sendable () -> Void)?

    private let _isReady = AtomicBool(false)
    public var isReady: Bool { _isReady.value }

    /// Direction-separated traffic ciphers: datagrams we emit are sealed with
    /// `sendCipher`, incoming ones opened with `receiveCipher`. Distinct keys
    /// keep the AES-GCM nonce spaces independent per direction.
    public var sendCipher: DatagramCipher? {
        get { cipherLock.lock(); defer { cipherLock.unlock() }; return _sendCipher }
        set { cipherLock.lock(); _sendCipher = newValue; cipherLock.unlock() }
    }

    public var receiveCipher: DatagramCipher? {
        get { cipherLock.lock(); defer { cipherLock.unlock() }; return _receiveCipher }
        set { cipherLock.lock(); _receiveCipher = newValue; cipherLock.unlock() }
    }

    public init() {
        queue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    // MARK: - Server side

    public func startListening(port: UInt16) throws {
        let params = NWParameters.udp
        params.allowLocalEndpointReuse = true
        listener = try NWListener(using: params, on: NWEndpoint.Port(rawValue: port)!)
        listener?.newConnectionHandler = { [weak self] conn in
            guard let self = self else { return }
            self.connection = conn
            conn.stateUpdateHandler = { [weak self] state in
                if case .ready = state {
                    ERDLog.network("[UDP] Listener connection ready")
                    self?._isReady.value = true
                    self?.onReady?()
                }
                self?.reconcileReceiving(conn, state: state)
            }
            conn.start(queue: self.queue)
            self.armReceiving(on: conn)
        }
        listener?.start(queue: queue)
    }

    // MARK: - Client side

    public func connect(host: String, port: UInt16) {
        let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(host), port: NWEndpoint.Port(rawValue: port)!)
        connect(to: endpoint)
    }

    public func connect(to endpoint: NWEndpoint) {
        let params = NWParameters.udp
        params.allowLocalEndpointReuse = true
        let conn = NWConnection(to: endpoint, using: params)
        queue.async { [weak self] in
            guard let self = self else { return }
            self.connection = conn
            conn.stateUpdateHandler = { [weak self] state in
                switch state {
                case .ready:
                    ERDLog.network("[UDP] Connected to \(endpoint)")
                    self?._isReady.value = true
                    self?.onReady?()
                case .failed(let e): ERDLog.error("[UDP] Connection failed: \(e)")
                default: break
                }
                self?.reconcileReceiving(conn, state: state)
            }
            conn.start(queue: self.queue)
            self.armReceiving(on: conn)
        }
    }

    // MARK: - Send

    public func send(_ data: Data, to endpoint: NWEndpoint? = nil) {
        guard let conn = connection else { return }
        conn.send(content: data, completion: .contentProcessed { error in
            if let error = error { ERDLog.error("[UDP] Send error: \(error)") }
        })
    }

    public func sendPacket(type: PacketType, payload: Data, to endpoint: NWEndpoint? = nil) {
        seqLock.lock()
        sequenceCounter += 1
        let seq = sequenceCounter
        seqLock.unlock()
        let ts = UInt32(truncatingIfNeeded: UInt64(Date().timeIntervalSince1970 * 1000))
        let header = PacketHeader(type: type, sequence: seq, timestamp: ts)
        var packet = header.serialize()
        if let cipher = sendCipher {
            guard let sealed = cipher.seal(payload, aad: packet) else {
                ERDLog.error("[UDP] Failed to seal \(type) packet")
                return
            }
            packet.append(sealed)
        } else {
            packet.append(payload)
        }
        send(packet, to: endpoint)
    }

    /// Send a small datagram to trigger the other side's listener to register us
    public func sendPing() {
        send(Data([0xFF]))
    }

    // MARK: - Stop

    public func stop() {
        let work = {
            self.connection?.cancel()
            self.connection = nil
            self.listener?.cancel()
            self.listener = nil
            self.sequenceCounter = 0
            self.isReceiving = false
            self._isReady.value = false
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    // MARK: - Internal

    private func reconcileReceiving(_ conn: NWConnection, state: NWConnection.State) {
        guard case .ready = state else { return }
        armReceiving(on: conn)
    }

    private func armReceiving(on conn: NWConnection) {
        let work = {
            guard self.connection === conn, !self.isReceiving else { return }
            self.isReceiving = true
            self.receiveLoop(on: conn)
        }
        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.async(execute: work)
        }
    }

    private func receiveLoop(on conn: NWConnection) {
        conn.receiveMessage { [weak self] content, _, _, error in
            guard let self = self else { return }
            if let data = content, data.count > 1 {
                if let packet = self.decodeDatagram(data) {
                    self.onReceive?(packet, conn.currentPath?.remoteEndpoint)
                }
            }
            if let error = error {
                ERDLog.error("[UDP] Receive error: \(error)")
            }
            // receiveMessage reports isComplete == true after datagrams on
            // listener-created UDP connections; only a dead connection may
            // stop the loop.
            let finish = {
                self.isReceiving = false
                switch conn.state {
                case .failed, .cancelled:
                    return
                default:
                    self.armReceiving(on: conn)
                }
            }
            if DispatchQueue.getSpecific(key: Self.queueKey) == true {
                finish()
            } else {
                self.queue.async(execute: finish)
            }
        }
    }

    private func decodeDatagram(_ data: Data) -> Data? {
        guard let cipher = receiveCipher else { return data }
        guard data.count > ERDConstants.packetHeaderSize,
              PacketHeader.deserialize(from: data.prefix(ERDConstants.packetHeaderSize)) != nil
        else { return nil }
        let header = data.prefix(ERDConstants.packetHeaderSize)
        guard let plaintext = cipher.open(data.subdata(in: ERDConstants.packetHeaderSize..<data.count),
                                          aad: Data(header))
        else { return nil }
        return header + plaintext
    }
}

import Foundation

public struct FrameHeaderPayload {
    public let frameId: UInt32
    public let width: UInt16
    public let height: UInt16
    public let isKeyFrame: Bool
    public let totalChunks: UInt16
    public let totalSize: UInt32

    public static let size = 16

    public init(frameId: UInt32, width: UInt16, height: UInt16, isKeyFrame: Bool, totalChunks: UInt16, totalSize: UInt32) {
        self.frameId = frameId; self.width = width; self.height = height
        self.isKeyFrame = isKeyFrame; self.totalChunks = totalChunks; self.totalSize = totalSize
    }

    public func serialize() -> Data {
        var d = Data(capacity: FrameHeaderPayload.size)
        var fid = frameId.littleEndian; d.append(Data(bytes: &fid, count: 4))
        var w = width.littleEndian;     d.append(Data(bytes: &w, count: 2))
        var h = height.littleEndian;    d.append(Data(bytes: &h, count: 2))
        var kf: UInt8 = isKeyFrame ? 1 : 0; d.append(Data(bytes: &kf, count: 1))
        var tc = totalChunks.littleEndian; d.append(Data(bytes: &tc, count: 2))
        // 1 byte padding
        var pad: UInt8 = 0; d.append(Data(bytes: &pad, count: 1))
        var ts = totalSize.littleEndian; d.append(Data(bytes: &ts, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> FrameHeaderPayload? {
        guard data.count >= size else { return nil }
        let fid = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let w = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let h = data.subdata(in: 6..<8).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let kf = data[8] != 0
        let tc = data.subdata(in: 9..<11).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let ts = data.subdata(in: 12..<16).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard tc <= ERDConstants.maxChunksPerFrame, ts <= ERDConstants.maxFrameBytes else { return nil }
        return FrameHeaderPayload(frameId: fid, width: w, height: h, isKeyFrame: kf, totalChunks: tc, totalSize: ts)
    }
}

public struct FrameChunkPayload {
    public let frameId: UInt32
    public let chunkIndex: UInt16
    public let chunkData: Data

    public static let headerSize = 6

    public init(frameId: UInt32, chunkIndex: UInt16, chunkData: Data) {
        self.frameId = frameId; self.chunkIndex = chunkIndex; self.chunkData = chunkData
    }

    public func serialize() -> Data {
        var d = Data(capacity: FrameChunkPayload.headerSize + chunkData.count)
        var fid = frameId.littleEndian; d.append(Data(bytes: &fid, count: 4))
        var ci = chunkIndex.littleEndian; d.append(Data(bytes: &ci, count: 2))
        d.append(chunkData)
        return d
    }

    public static func deserialize(from data: Data) -> FrameChunkPayload? {
        guard data.count >= headerSize else { return nil }
        let fid = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let ci = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let chunk = data.subdata(in: headerSize..<data.count)
        return FrameChunkPayload(frameId: fid, chunkIndex: ci, chunkData: chunk)
    }
}

import Foundation
import CryptoKit

public struct SessionCandidate: Codable, Equatable {
    public let role: String
    public let localIP: String
    public let localPort: UInt16
    public let publicIP: String
    public let publicPort: UInt16

    public init(role: String, localIP: String, localPort: UInt16, publicIP: String, publicPort: UInt16) {
        self.role = role; self.localIP = localIP; self.localPort = localPort
        self.publicIP = publicIP; self.publicPort = publicPort
    }
}

/// NAT-traversal candidate exchange over a public ntfy.sh topic.
///
/// The topic is a 256-bit hash of the shared PIN and candidate payloads are
/// AES-GCM encrypted under a key derived from the same PIN, so an outside
/// observer can neither enumerate topics for a given PIN space nor read the
/// exchanged addresses. Both peers poll until the other side's candidate
/// shows up instead of failing on the first empty response.
public class SignalingClient {
    private let role: String
    private let topic: String
    private let payloadKey: SymmetricKey
    private let lock = NSLock()
    private var isSearching = false

    public init(pin: String, role: String) {
        self.role = role
        let ikm = Data(pin.utf8)
        let seed = HKDF.derive(ikm: ikm, salt: Data("erd/signaling/v3".utf8), info: Data("erd/topic".utf8))
        self.topic = "erd3-" + seed.map { String(format: "%02x", $0) }.joined()
        let key = HKDF.derive(ikm: ikm, salt: Data("erd/signaling/v3".utf8), info: Data("erd/payload-key".utf8))
        self.payloadKey = SymmetricKey(data: key)
    }

    deinit { stop() }

    private static func encrypt(_ payload: Data, using key: SymmetricKey) throws -> String {
        let box = try AES.GCM.seal(payload, using: key)
        return Data(box.combined!).base64EncodedString()
    }

    private static func peerCandidate(in data: Data, excludingRole role: String, key: SymmetricKey) -> SessionCandidate? {
        let lines = String(data: data, encoding: .utf8)?.split(separator: "\n") ?? []
        for line in lines.reversed() {
            guard let lineData = line.data(using: .utf8),
                  let envelope = try? JSONSerialization.jsonObject(with: lineData) as? [String: Any],
                  let message = envelope["message"] as? String,
                  let raw = Data(base64Encoded: message),
                  let box = try? AES.GCM.SealedBox(combined: raw),
                  let payload = try? AES.GCM.open(box, using: key),
                  let candidate = try? JSONDecoder().decode(SessionCandidate.self, from: payload),
                  candidate.role != role
            else { continue }
            return candidate
        }
        return nil
    }

    public func exchangeCandidate(_ local: SessionCandidate) async throws -> SessionCandidate {
        let payload = try JSONEncoder().encode(local)
        let message = try Self.encrypt(payload, using: payloadKey)
        let url = URL(string: "https://ntfy.sh/\(topic)")!

        var post = URLRequest(url: url)
        post.httpMethod = "POST"
        post.httpBody = Data(message.utf8)
        post.setValue("text/plain", forHTTPHeaderField: "Content-Type")

        ERDLog.network("[Signaling] Posting candidate")
        _ = try await URLSession.shared.data(for: post)

        lock.lock()
        isSearching = true
        lock.unlock()

        let deadline = Date().addingTimeInterval(ERDConstants.connectionTimeout)
        var poll = URLRequest(url: URL(string: "https://ntfy.sh/\(topic)/json?poll=1&since=10m")!)
        poll.timeoutInterval = 10

        while Date() < deadline {
            lock.lock()
            let active = isSearching
            lock.unlock()
            guard active else { throw CancellationError() }
            try Task.checkCancellation()

            if let (data, _) = try? await URLSession.shared.data(for: poll),
               let candidate = Self.peerCandidate(in: data, excludingRole: role, key: payloadKey) {
                return candidate
            }
            try await Task.sleep(nanoseconds: 1_000_000_000)
        }
        throw NSError(domain: "Signaling", code: 2,
                      userInfo: [NSLocalizedDescriptionKey: "Signaling timeout waiting for peer"])
    }

    public func stop() {
        lock.lock()
        isSearching = false
        lock.unlock()
    }
}

import Foundation
import AppKit

/// Monitors the system pasteboard for text changes and provides loop prevention
/// for bidirectional clipboard sync between host and client.
///
/// Loop prevention strategy:
/// - Tracks `changeCount` to detect local pasteboard changes
/// - When applying remote text, records the resulting changeCount to suppress the echo
/// - Uses content hash dedup to avoid sending identical text back
public class ClipboardMonitor {
    private let pasteboard = NSPasteboard.general
    private var pollTimer: DispatchSourceTimer?
    private let lock = NSLock()

    // Concealed/transient pasteboard entries (password managers, 2FA copies)
    // must never leave the machine.
    private static let suppressedPasteboardTypes = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
    ]

    /// The changeCount after our last write, used to suppress echo
    private var lastWrittenChangeCount: Int = -1
    /// Hash of the last text we sent or applied, for content-level dedup
    private var lastTextHash: Int = 0
    /// Whether monitoring is active
    private var isRunning = false
    /// Last observed changeCount
    private var lastChangeCount: Int = 0

    private let onLocalChange: (String) -> Void

    /// - Parameter onLocalChange: Called when the local pasteboard text changes
    ///   (excluding changes applied via `applyRemoteText`).
    public init(onLocalChange: @escaping (String) -> Void) {
        self.onLocalChange = onLocalChange
    }

    public func start() {
        lock.lock()
        guard !isRunning else { lock.unlock(); return }
        isRunning = true
        lastChangeCount = pasteboard.changeCount
        lastWrittenChangeCount = -1
        lastTextHash = 0
        lock.unlock()

        let timer = DispatchSource.makeTimerSource(queue: .main)
        timer.schedule(deadline: .now() + 0.5, repeating: 0.5)
        timer.setEventHandler { [weak self] in
            self?.poll()
        }
        timer.resume()
        pollTimer = timer
    }

    public func stop() {
        lock.lock()
        isRunning = false
        lock.unlock()
        pollTimer?.cancel()
        pollTimer = nil
    }

    /// Apply text received from the remote peer to the local pasteboard.
    /// The resulting changeCount is recorded so the next poll won't echo it back.
    public func applyRemoteText(_ text: String) {
        let hash = text.hashValue
        lock.lock()
        lastTextHash = hash
        lock.unlock()

        DispatchQueue.main.async { [weak self] in
            guard let self = self else { return }
            self.pasteboard.clearContents()
            self.pasteboard.setString(text, forType: .string)

            self.lock.lock()
            self.lastWrittenChangeCount = self.pasteboard.changeCount
            self.lastChangeCount = self.pasteboard.changeCount
            self.lock.unlock()
        }
    }

    private func poll() {
        let currentCount = pasteboard.changeCount

        lock.lock()
        let running = isRunning
        let prevCount = lastChangeCount
        let writtenCount = lastWrittenChangeCount
        let prevHash = lastTextHash
        lock.unlock()

        guard running, currentCount != prevCount else { return }

        // Suppress echo: if this changeCount matches what we just wrote, skip
        if currentCount == writtenCount {
            lock.lock()
            lastChangeCount = currentCount
            lock.unlock()
            return
        }

        lock.lock()
        lastChangeCount = currentCount
        lock.unlock()

        guard let text = pasteboard.string(forType: .string), !text.isEmpty else { return }

        if let types = pasteboard.types,
           types.contains(where: { Self.suppressedPasteboardTypes.contains($0.rawValue) }) {
            return
        }

        // Content-level dedup: don't send if identical to last sent/applied text
        let hash = text.hashValue
        guard hash != prevHash else { return }

        // Check size limit
        guard let textData = text.data(using: .utf8),
              textData.count <= ERDConstants.maxClipboardTextBytes else { return }

        lock.lock()
        lastTextHash = hash
        lock.unlock()

        onLocalChange(text)
    }
}

import Foundation
import Network
import CoreMedia
import CoreGraphics

public class ServerCore {
    public static let shared = ServerCore()

    private let tcpChannel = TCPChannel()
    private let udpChannel = UDPChannel()
    private var frameSender: FrameSender?
    private var inputReceiver: InputReceiver?
    private let screenCapture: FrameSource
    private var videoEncoder: VideoEncoder?
    private var hostname: String = ""
    public private(set) var isRunning = false
    private var isStreaming = AtomicBool(false)
    // Protects inputReceiver, frameSender, videoEncoder from concurrent access
    // between tcpChannel.onReceive (TCP queue) and startStreaming/stopStreaming (async context).
    private let stateQueue = DispatchQueue(label: "eclipticrd.server.state")

    private var heartbeatTimer: DispatchSourceTimer?
    private let heartbeatQueue = DispatchQueue(label: "eclipticrd.server.heartbeat")
    private var lastPongTime: Date = Date()
    private let pongLock = NSLock()

    private var clipboardMonitor: ClipboardMonitor?
    private var peerCapabilities: HandshakeCapabilities = []
    private var activeStreamConfig: StreamConfiguration?

    public var onRunningChanged: (@Sendable (Bool) -> Void)?
    public var onPairingRequest: (@Sendable (String, @escaping @Sendable (Bool) -> Void) -> Void)?
    public var onStartFailed: (@Sendable (String) -> Void)?

    private var sessionPairingKey: Data?
    private var sessionSalt = Data()
    private var audioFrameCounter: UInt32 = 0

    private init(frameSource: FrameSource = ScreenCapture()) {
        self.screenCapture = frameSource
    }

    /// Test seam: build an orchestrator around a synthetic capture source so
    /// session logic can be exercised without ScreenCaptureKit or TCC grants.
    public static func makeForTesting(frameSource: FrameSource) -> ServerCore {
        ServerCore(frameSource: frameSource)
    }

    public func start(pin: String? = nil) async {
        hostname = ProcessInfo.processInfo.hostName

        do {
            // 1. Start TCP listener for control/input
            try tcpChannel.startListening(port: ERDConstants.tcpPort)
            isRunning = true
            onRunningChanged?(true)

            // 2. Start UDP listener for video frames
            try udpChannel.startListening(port: ERDConstants.udpPort)
            ERDLog.info("[Server] Listening on UDP:\(ERDConstants.udpPort)")

            // 3. Set up handlers BEFORE advertising/signaling so incoming connections are handled
            tcpChannel.onConnect = { [weak self] in
                ERDLog.info("[Server] TLS channel established, awaiting client handshake")
            }
            tcpChannel.onDisconnect = { [weak self] in
                ERDLog.info("[Server] Client disconnected")
                Task { await self?.stopStreaming() }
            }
            tcpChannel.onReceive = { [weak self] data in
                guard let self = self else { return }
                guard data.count >= ERDConstants.packetHeaderSize else { return }
                guard let header = PacketHeader.deserialize(from: data) else {
                    return
                }
                let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

                switch header.type {
                case .inputEvent:
                    let receiver = self.stateQueue.sync { self.inputReceiver }
                    receiver?.handleInputEvent(payload)
                case .control:
                    if let msg = ControlMessage.deserialize(from: payload) {
                        switch msg.type {
                        case .requestKeyFrame:
                            let encoder = self.stateQueue.sync { self.videoEncoder }
                            encoder?.forceKeyFrame()
                        case .startStream: Task { await self.startStreaming() }
                        case .stopStream: Task { await self.stopStreaming() }
                        case .disconnect: Task { await self.stop() }
                        case .ping: break
                        case .streamConfigRequest:
                            if let data = msg.payload,
                               let req = StreamConfigurationRequestPayload.deserialize(from: data) {
                                Task { await self.handleStreamConfigRequest(req) }
                            }
                        case .streamConfigResponse, .streamConfigReject, .streamConfigError:
                            break // Server doesn't process these
                        case .clipboardSyncRequest:
                            break // Clipboard start/stop handled at session level
                        case .clipboardSyncUpdate:
                            if let data = msg.payload,
                               let update = ClipboardSyncUpdatePayload.deserialize(from: data) {
                                self.handleClipboardUpdate(update)
                            }
                        case .clipboardSyncError:
                            if let data = msg.payload,
                               let err = ClipboardSyncErrorPayload.deserialize(from: data) {
                                ERDLog.warning("[Server] Clipboard sync error from client: \(err.message)")
                            }
                        case .pong:
                            self.pongLock.lock()
                            self.lastPongTime = Date()
                            self.pongLock.unlock()
                        case .bitrateAdjust:
                            if let data = msg.payload,
                               let adj = BitrateAdjustPayload.deserialize(from: data) {
                                let newBitrate = Int(adj.targetBitrate)
                                ERDLog.info("[Server] Bitrate adjust request: \(newBitrate)")
                                let encoder = self.stateQueue.sync { self.videoEncoder }
                                encoder?.updateBitrate(newBitrate)
                            }
                        }
                    }
                case .handshake:
                    self.handleClientHandshake(payload)
                case .pairingRequest:
                    if let request = PairingRequestPayload.deserialize(from: payload) {
                        Task { await self.handlePairingRequest(request) }
                    }
                case .pairingGrant, .pairingReject:
                    break // host never receives these
                default: break
                }
            }

            // 4. Advertise via Bonjour (handlers are ready for incoming connections)
            tcpChannel.advertiseService(name: hostname)
            ERDLog.info("[Server] Advertising as '\(hostname)' via Bonjour")

            // 5. A live pairing window keeps the bootstrap PSK available for
            // new devices; an explicit PIN (internet mode) doubles as the
            // signaling topic seed. Hosting without a PIN leaves pairing
            // closed until the app opens a window explicitly.
            if let pin {
                let activePIN = beginPairingSession(explicitPIN: pin)
                await startSignaling(pin: activePIN)
            }

            ERDLog.info("[Server] Waiting for client connection...")
        } catch {
            isRunning = false
            onRunningChanged?(false)
            onStartFailed?(error.localizedDescription)
            ERDLog.error("[Server] Fatal error: \(error)")
        }
    }

    /// Open a fresh pairing window (new PIN) and refresh the listener PSKs.
    @discardableResult
    public func beginPairingSession(explicitPIN: String? = nil) -> String {
        let pin = PairingManager.shared.beginPairing(explicitPIN: explicitPIN)
        tcpChannel.updateSecurity(.psk(PairingManager.shared.hostPSKs()))
        return pin
    }

    private func startSignaling(pin: String) async {
        do {
            let stun = STUNClient()
            let (publicIP, publicPort) = try await stun.fetchPublicIP()
            ERDLog.info("[Server] STUN Public IP: \(publicIP):\(publicPort)")

            let localIP = NetworkUtils.getLocalIP() ?? "127.0.0.1"
            let signaling = SignalingClient(pin: pin, role: "server")
            let ourCandidate = SessionCandidate(role: "server", localIP: localIP, localPort: ERDConstants.tcpPort,
                                                  publicIP: publicIP, publicPort: publicPort)

            ERDLog.info("[Server] Exchanging candidates via PIN: \(pin)")
            let _ = try await signaling.exchangeCandidate(ourCandidate)
            signaling.stop()
            ERDLog.info("[Server] Signaling complete, waiting for client TCP connection...")
        } catch {
            ERDLog.error("[Server] Signaling failed: \(error)")
        }
    }

    private func startStreaming() async {
        guard !isStreaming.value else {
            return
        }

        isStreaming.value = true

        let info = screenCapture.getDisplayInfo()
        let initialConfiguration = StreamConfiguration(
            width: UInt32(info.pixelWidth),
            height: UInt32(info.pixelHeight),
            bitrate: UInt32(ERDConstants.defaultBitrate),
            framesPerSecond: UInt16(ERDConstants.defaultFPS)
        )

        stateQueue.sync {
            inputReceiver = InputReceiver(screenWidth: CGFloat(info.width), screenHeight: CGFloat(info.height))
            frameSender = FrameSender(udpChannel: udpChannel)
            activeStreamConfig = initialConfiguration
        }

        // Send handshake to client (logical resolution for coordinate mapping)
        let handshake = HandshakePayload(hostname: hostname, screenWidth: UInt16(info.width),
                                          screenHeight: UInt16(info.height), scaleFactor: Float(info.scale),
                                          capabilities: [.streamConfiguration, .textClipboardSync])
        let header = PacketHeader(type: .handshakeAck, sequence: 0, timestamp: 0)
        var packet = header.serialize()
        packet.append(handshake.serialize())
        tcpChannel.send(packet)

        let preferredFPS = UserDefaults.standard.integer(forKey: "preferredFPS")
        let fps = preferredFPS > 0 ? preferredFPS : ERDConstants.defaultFPS

        // Setup pipeline: capture → encode → send (physical resolution for encoding)
        let encoder = makeVideoEncoder(
            width: info.pixelWidth,
            height: info.pixelHeight,
            bitrate: ERDConstants.defaultBitrate,
            fps: fps
        )

        stateQueue.sync { videoEncoder = encoder }

        screenCapture.onFrame = { [weak self] sampleBuffer in
            guard let self = self else { return }
            let encoder = self.stateQueue.sync { self.videoEncoder }
            encoder?.encode(sampleBuffer)
        }
        screenCapture.onCursorPosition = { [weak self] point in
            guard let self = self else { return }
            let nx = Float(point.x) / Float(info.width)
            let ny = Float(point.y) / Float(info.height)
            let sender = self.stateQueue.sync { self.frameSender }
            sender?.sendCursorUpdate(x: nx, y: ny)
        }
        screenCapture.onAudio = { [weak self] sampleBuffer in
            self?.handleAudioFrame(sampleBuffer)
        }

        do {
            try encoder.start()
            try await screenCapture.start(fps: fps)
            startHeartbeat()
            startClipboardSync()
            ERDLog.info("[Server] Streaming started: \(info.width)x\(info.height)")
        } catch {
            isStreaming.value = false
            stopHeartbeat()
            do { try await screenCapture.stop() } catch { }
            stateQueue.sync {
                videoEncoder?.stop()
                videoEncoder = nil
                frameSender = nil
                inputReceiver = nil
                activeStreamConfig = nil
            }
            ERDLog.error("[Server] Failed to start streaming: \(error)")
        }
    }

    private func stopStreaming() async {
        guard isStreaming.value else { return }
        isStreaming.value = false
        stopClipboardSync()
        stopHeartbeat()
        do { try await screenCapture.stop() } catch { ERDLog.error("[Server] Error stopping capture: \(error)") }

        stateQueue.sync {
            videoEncoder?.stop()
            videoEncoder = nil
            frameSender = nil
            inputReceiver = nil
            activeStreamConfig = nil
        }
        ERDLog.info("[Server] Streaming stopped")
    }

    public func stop() async {
        await stopStreaming()
        stateQueue.sync {
            self.sessionPairingKey = nil
            self.sessionSalt = Data()
        }
        tcpChannel.stop()
        udpChannel.stop()
        isRunning = false
        onRunningChanged?(false)
    }

    // MARK: - Pairing & Session Trust

    private func handleClientHandshake(_ payload: Data) {
        guard let hs = HandshakePayload.deserialize(from: payload) else { return }
        guard hs.protocolVersion == ERDConstants.protocolVersion else {
            ERDLog.warning("[Server] Rejecting client with protocol v\(hs.protocolVersion)")
            tcpChannel.disconnectConnection()
            return
        }
        guard let key = PairingStore.load(id: hs.pairingID)?.key else {
            ERDLog.warning("[Server] Handshake from unknown pairing id, disconnecting")
            tcpChannel.disconnectConnection()
            return
        }
        stateQueue.sync {
            self.peerCapabilities = hs.capabilities
            self.sessionPairingKey = key
            self.sessionSalt = hs.sessionSalt
        }
        applyUDPCiphers()
        ERDLog.info("[Server] Client handshake: \(hs.hostname) caps=\(hs.capabilities.rawValue)")
        if isStreaming.value {
            startClipboardSync()
        } else {
            Task { await self.startStreaming() }
        }
    }

    private func applyUDPCiphers() {
        let (key, salt) = stateQueue.sync { (self.sessionPairingKey, self.sessionSalt) }
        guard let key, salt.count == 16 else { return }
        udpChannel.sendCipher = DatagramCipher.udpCipher(masterKey: key, sessionSalt: salt, clientToHost: false)
        udpChannel.receiveCipher = DatagramCipher.udpCipher(masterKey: key, sessionSalt: salt, clientToHost: true)
    }

    private func handlePairingRequest(_ request: PairingRequestPayload) async {
        guard PairingManager.shared.isPairingActive else {
            sendPairingReject(.pairingDisabled)
            return
        }
        // Hold the channel open while the host user decides
        tcpChannel.setTimeout(ERDConstants.pairingPINExpiry)

        let approved = await withCheckedContinuation { (continuation: CheckedContinuation<Bool, Never>) in
            self.onPairingRequest?(request.hostname) { approved in
                continuation.resume(returning: approved)
            }
        }

        if approved {
            let record = PairingManager.shared.grantPairing(hostname: request.hostname)
            let grant = PairingGrantPayload(pairingID: record.id, hostName: hostname, key: record.key)
            sendPairingPacket(.pairingGrant, grant.serialize())
            tcpChannel.updateSecurity(.psk(PairingManager.shared.hostPSKs()))
            ERDLog.info("[Server] Granted pairing to \(request.hostname)")
        } else {
            sendPairingReject(.deniedByHost)
            tcpChannel.disconnectConnection()
        }
    }

    private func sendPairingReject(_ reason: PairingRejectReason) {
        sendPairingPacket(.pairingReject, PairingRejectPayload(reason: reason).serialize())
    }

    private func sendPairingPacket(_ type: PacketType, _ payload: Data) {
        let header = PacketHeader(type: type, sequence: 0, timestamp: 0)
        var packet = header.serialize()
        packet.append(payload)
        tcpChannel.send(packet)
    }

    // MARK: - Stream Configuration

    private func handleStreamConfigRequest(_ request: StreamConfigurationRequestPayload) async {
        let desired = request.desiredConfiguration

        // Validate requested dimensions
        let info = screenCapture.getDisplayInfo()
        let maxW = UInt32(info.pixelWidth)
        let maxH = UInt32(info.pixelHeight)

        if desired.width > maxW || desired.height > maxH || desired.width == 0 || desired.height == 0 {
            let reject = StreamConfigurationRejectPayload(
                requestID: request.requestID,
                reason: .unsupportedDimensions,
                message: "Dimensions must be 1..\(maxW)x\(maxH)")
            let msg = ControlMessage(type: .streamConfigReject, payload: reject.serialize())
            tcpChannel.sendControl(msg)
            return
        }

        if desired.framesPerSecond == 0 || desired.framesPerSecond > 120 {
            let reject = StreamConfigurationRejectPayload(
                requestID: request.requestID,
                reason: .unsupportedFPS,
                message: "FPS must be 1..120")
            let msg = ControlMessage(type: .streamConfigReject, payload: reject.serialize())
            tcpChannel.sendControl(msg)
            return
        }

        let clampedBitrate = max(UInt32(ERDConstants.minBitrate), min(desired.bitrate, UInt32(ERDConstants.maxBitrate)))

        let currentConfiguration = stateQueue.sync { self.activeStreamConfig }
        let captureDimensionsChanged = currentConfiguration.map {
            Int($0.width) != Int(desired.width) || Int($0.height) != Int(desired.height)
        } ?? true

        if captureDimensionsChanged {
            let encoder = makeVideoEncoder(
                width: Int(desired.width),
                height: Int(desired.height),
                bitrate: Int(clampedBitrate),
                fps: Int(desired.framesPerSecond)
            )

            do {
                try encoder.start()
            } catch {
                encoder.stop()
                let errPayload = StreamConfigurationErrorPayload(
                    requestID: request.requestID,
                    errorCode: .invalidRequest,
                    message: "Failed to restart encoder: \(error.localizedDescription)")
                let msg = ControlMessage(type: .streamConfigError, payload: errPayload.serialize())
                tcpChannel.sendControl(msg)
                return
            }

            let oldEncoder = stateQueue.sync { () -> VideoEncoder? in
                let encoder = self.videoEncoder
                self.videoEncoder = nil
                return encoder
            }

            do {
                try await screenCapture.updateConfiguration(
                    width: Int(desired.width),
                    height: Int(desired.height),
                    fps: Int(desired.framesPerSecond)
                )
            } catch {
                encoder.stop()
                stateQueue.sync { self.videoEncoder = oldEncoder }
                let errPayload = StreamConfigurationErrorPayload(
                    requestID: request.requestID,
                    errorCode: .invalidRequest,
                    message: "Failed to update capture: \(error.localizedDescription)")
                let msg = ControlMessage(type: .streamConfigError, payload: errPayload.serialize())
                tcpChannel.sendControl(msg)
                return
            }

            stateQueue.sync { self.videoEncoder = encoder }
            oldEncoder?.stop()
        } else {
            do {
                try await screenCapture.updateConfiguration(
                    width: Int(desired.width),
                    height: Int(desired.height),
                    fps: Int(desired.framesPerSecond)
                )
            } catch {
                let errPayload = StreamConfigurationErrorPayload(
                    requestID: request.requestID,
                    errorCode: .invalidRequest,
                    message: "Failed to update capture: \(error.localizedDescription)")
                let msg = ControlMessage(type: .streamConfigError, payload: errPayload.serialize())
                tcpChannel.sendControl(msg)
                return
            }

            let encoder = stateQueue.sync { self.videoEncoder }
            encoder?.updateBitrate(Int(clampedBitrate))
            encoder?.updateFPS(Int(desired.framesPerSecond))
        }

        let applied = StreamConfiguration(
            width: desired.width,
            height: desired.height,
            bitrate: clampedBitrate,
            framesPerSecond: desired.framesPerSecond)
        stateQueue.sync { activeStreamConfig = applied }

        let response = StreamConfigurationResponsePayload(requestID: request.requestID, activeConfiguration: applied)
        let msg = ControlMessage(type: .streamConfigResponse, payload: response.serialize())
        tcpChannel.sendControl(msg)
        ERDLog.info("[Server] Stream config applied: \(applied.width)x\(applied.height) @\(applied.framesPerSecond)fps \(applied.bitrate)bps")
    }

    private func makeVideoEncoder(width: Int, height: Int, bitrate: Int, fps: Int) -> VideoEncoder {
        let encoder = VideoEncoder(width: width, height: height, bitrate: bitrate, fps: fps)
        encoder.onEncodedFrame = { [weak self] data, isKeyFrame in
            guard let self = self else { return }
            let sender = self.stateQueue.sync { self.frameSender }
            let activeConfiguration = self.stateQueue.sync { self.activeStreamConfig }
            let width = Int(activeConfiguration?.width ?? UInt32(width))
            let height = Int(activeConfiguration?.height ?? UInt32(height))
            sender?.sendFrame(data: data, width: width, height: height, isKeyFrame: isKeyFrame)
        }
        return encoder
    }

    // MARK: - Clipboard Sync

    private func startClipboardSync() {
        let existingMonitor = stateQueue.sync { self.clipboardMonitor }
        guard existingMonitor == nil else {
            return
        }

        let peerCaps = stateQueue.sync { self.peerCapabilities }
        guard peerCaps.contains(.textClipboardSync) else {
            ERDLog.info("[Server] Peer does not support clipboard sync, skipping")
            return
        }

        let monitor = ClipboardMonitor { [weak self] text in
            guard let self = self else { return }
            let update = ClipboardSyncUpdatePayload(
                requestID: 0,
                direction: .hostToClient,
                origin: .localPasteboard,
                text: text)
            if let data = update.serialize() {
                let msg = ControlMessage(type: .clipboardSyncUpdate, payload: data)
                self.tcpChannel.sendControl(msg)
            }
        }
        stateQueue.sync { self.clipboardMonitor = monitor }
        monitor.start()
        ERDLog.info("[Server] Clipboard sync started")
    }

    private func stopClipboardSync() {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.stop()
        stateQueue.sync { self.clipboardMonitor = nil }
    }

    private func handleClipboardUpdate(_ update: ClipboardSyncUpdatePayload) {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.applyRemoteText(update.text)
        ERDLog.info("[Server] Clipboard received from client (\(update.text.count) chars)")
    }

    // MARK: - Heartbeat

    private func startHeartbeat() {
        stopHeartbeat()
        pongLock.lock()
        lastPongTime = Date()
        pongLock.unlock()

        let timer = DispatchSource.makeTimerSource(queue: heartbeatQueue)
        timer.schedule(deadline: .now() + ERDConstants.heartbeatInterval,
                       repeating: ERDConstants.heartbeatInterval)
        timer.setEventHandler { [weak self] in
            guard let self = self, self.isStreaming.value else { return }

            self.tcpChannel.sendControl(ControlMessage(type: .ping))

            self.pongLock.lock()
            let elapsed = Date().timeIntervalSince(self.lastPongTime)
            self.pongLock.unlock()

            if elapsed > ERDConstants.heartbeatInterval * 3 {
                ERDLog.warning("[Server] Client heartbeat timeout (\(elapsed)s)")
                Task { await self.stopStreaming() }
                self.tcpChannel.disconnectConnection()
            }
        }
        timer.resume()
        heartbeatTimer = timer
        ERDLog.info("[Server] Heartbeat started")
    }

    private func stopHeartbeat() {
        heartbeatTimer?.cancel()
        heartbeatTimer = nil
    }

    private func handleAudioFrame(_ sampleBuffer: CMSampleBuffer) {
        guard isStreaming.value else { return }
        guard let blockBuffer = CMSampleBufferGetDataBuffer(sampleBuffer) else { return }

        var length = 0
        var dataPointer: UnsafeMutablePointer<Int8>?
        let status = CMBlockBufferGetDataPointer(blockBuffer, atOffset: 0, lengthAtOffsetOut: nil, totalLengthOut: &length, dataPointerOut: &dataPointer)

        guard status == noErr, let pointer = dataPointer, length > 0 else { return }

        let audioData = Data(bytes: pointer, count: length)
        sendAudio(audioData)
    }

    private func sendAudio(_ audioData: Data) {
        let maxChunk = ERDConstants.maxPayloadSize - 8 // [frameId u32][fragIdx u16][fragCount u16]
        let fragmentCount = Int(ceil(Double(audioData.count) / Double(maxChunk)))
        guard fragmentCount > 0, fragmentCount <= Int(UInt16.max) else { return }
        audioFrameCounter &+= 1
        let frameId = audioFrameCounter

        for index in 0..<fragmentCount {
            let start = index * maxChunk
            let end = min(start + maxChunk, audioData.count)
            var payload = Data(capacity: 8 + (end - start))
            var id = frameId.littleEndian; payload.append(Data(bytes: &id, count: 4))
            var idx = UInt16(index).littleEndian; payload.append(Data(bytes: &idx, count: 2))
            var total = UInt16(fragmentCount).littleEndian; payload.append(Data(bytes: &total, count: 2))
            payload.append(audioData.subdata(in: start..<end))
            udpChannel.sendPacket(type: .audioFrame, payload: payload)
        }
    }
}

import Foundation
import CoreGraphics
import ApplicationServices

public class InputReceiver {
    private var screenWidth: CGFloat
    private var screenHeight: CGFloat
    private let rateLock = NSLock()
    private var eventTokens: Double = Double(ERDConstants.inputBurstCapacity)
    private var lastRefillTime = Date()

    public init(screenWidth: CGFloat, screenHeight: CGFloat) {
        self.screenWidth = screenWidth
        self.screenHeight = screenHeight
    }

    public func updateScreenSize(width: CGFloat, height: CGFloat) {
        self.screenWidth = width
        self.screenHeight = height
    }

    public func handleInputEvent(_ data: Data) {
        guard AXIsProcessTrusted() else { return }
        guard let event = InputEventPayload.deserialize(from: data) else { return }
        guard allowInputEvent() else { return }

        let x = CGFloat(min(max(event.x, 0), 1)) * screenWidth
        let y = CGFloat(min(max(event.y, 0), 1)) * screenHeight
        let point = CGPoint(x: x, y: y)

        let source = CGEventSource(stateID: .hidSystemState)

        switch event.type {
        case .mouseMove:
            post(.mouseMoved, at: point, button: .left, source: source)
        case .leftMouseDragged:
            post(.leftMouseDragged, at: point, button: .left, source: source)
        case .rightMouseDragged:
            post(.rightMouseDragged, at: point, button: .right, source: source)
        case .leftMouseDown:
            post(.leftMouseDown, at: point, button: .left, source: source)
        case .leftMouseUp:
            post(.leftMouseUp, at: point, button: .left, source: source)
        case .rightMouseDown:
            post(.rightMouseDown, at: point, button: .right, source: source)
        case .rightMouseUp:
            post(.rightMouseUp, at: point, button: .right, source: source)
        case .scrollWheel:
            if let cgEvent = CGEvent(scrollWheelEvent2Source: source, units: .pixel, wheelCount: 2,
                                     wheel1: Int32(event.scrollDeltaY), wheel2: Int32(event.scrollDeltaX), wheel3: 0) {
                cgEvent.post(tap: .cghidEventTap)
            }
        case .keyDown:
            postKey(code: event.keyCode, down: true, modifiers: event.modifiers, source: source)
        case .keyUp:
            postKey(code: event.keyCode, down: false, modifiers: event.modifiers, source: source)
        case .flagsChanged:
            if let cgEvent = CGEvent(keyboardEventSource: source, virtualKey: event.keyCode, keyDown: true) {
                var flags = CGEventFlags()
                if event.modifiers.contains(.shift)   { flags.insert(.maskShift) }
                if event.modifiers.contains(.control) { flags.insert(.maskControl) }
                if event.modifiers.contains(.option)  { flags.insert(.maskAlternate) }
                if event.modifiers.contains(.command) { flags.insert(.maskCommand) }
                if event.modifiers.contains(.capsLock) { flags.insert(.maskAlphaShift) }
                cgEvent.flags = flags
                cgEvent.post(tap: .cghidEventTap)
            }
        }
    }

    /// Token bucket: sustained 200 events/s with a short burst allowance,
    /// so a hostile peer cannot flood the host UI with synthetic input.
    private func allowInputEvent() -> Bool {
        rateLock.lock(); defer { rateLock.unlock() }
        let now = Date()
        eventTokens = min(Double(ERDConstants.inputBurstCapacity),
                          eventTokens + now.timeIntervalSince(lastRefillTime) * Double(ERDConstants.maxInputEventsPerSecond))
        lastRefillTime = now
        guard eventTokens >= 1 else { return false }
        eventTokens -= 1
        return true
    }

    private func post(_ type: CGEventType, at point: CGPoint, button: CGMouseButton, source: CGEventSource?) {
        if let cgEvent = CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: button) {
            cgEvent.post(tap: .cghidEventTap)
        }
    }

    private func postKey(code: UInt16, down: Bool, modifiers: ModifierFlags, source: CGEventSource?) {
        if let cgEvent = CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(code), keyDown: down) {
            var flags = CGEventFlags()
            if modifiers.contains(.shift)   { flags.insert(.maskShift) }
            if modifiers.contains(.control) { flags.insert(.maskControl) }
            if modifiers.contains(.option)  { flags.insert(.maskAlternate) }
            if modifiers.contains(.command) { flags.insert(.maskCommand) }
            cgEvent.flags = flags
            cgEvent.post(tap: .cghidEventTap)
        }
    }
}

import Foundation
import Network
import MetalKit
import AppKit
import Security

public class ClientCore {
    public static let shared = ClientCore()

    private let tcpChannel = TCPChannel()
    private let udpChannel = UDPChannel()
    private let frameReceiver = FrameReceiver()
    private let decoder = VideoDecoder()
    private let audioPlayer = ClientAudioPlayer()
    public let isAudioMuted = AtomicBool(false)
    private var renderer: MetalRenderer?
    private var inputSender: InputSender?
    // Protects inputSender from concurrent access between TCP callbacks and UI thread.
    private let stateQueue = DispatchQueue(label: "eclipticrd.client.state")

    private var abrTimer: DispatchSourceTimer?
    private let abrQueue = DispatchQueue(label: "eclipticrd.client.abr")
    private var currentBitrate: Int = ERDConstants.defaultBitrate
    private var lowLossStartTime: Date?

    private var clipboardMonitor: ClipboardMonitor?
    private var peerCapabilities: HandshakeCapabilities = []
    private var nextStreamConfigRequestID: UInt32 = 1
    private var activePairing: PairingRecord?
    private var sessionPairingKey: Data?
    private var sessionSalt = Data()
    private var audioFragments: [UInt32: (chunks: [UInt16: Data], total: UInt16)] = [:]
    public var onStreamConfigResponse: (@Sendable (StreamConfigurationResponsePayload) -> Void)?
    public var onStreamConfigRejected: (@Sendable (StreamConfigurationRejectPayload) -> Void)?
    public var onStreamConfigError: (@Sendable (StreamConfigurationErrorPayload) -> Void)?

    public var onSessionReady: (@Sendable () -> Void)?
    public var onServerIdentity: (@Sendable (String) -> Void)?
    public var onDisconnected: (@Sendable () -> Void)?
    public var onError: (@Sendable (String) -> Void)?
    public var onClipboardSynced: (@Sendable (String) -> Void)?

    public var serverHost: String?
    private var udpTargetHost: String?
    private var _serverScreenWidth: Int = 0
    private var _serverScreenHeight: Int = 0
    public var serverScreenWidth: Int {
        get { stateQueue.sync { _serverScreenWidth } }
        set { stateQueue.sync { _serverScreenWidth = newValue } }
    }
    public var serverScreenHeight: Int {
        get { stateQueue.sync { _serverScreenHeight } }
        set { stateQueue.sync { _serverScreenHeight = newValue } }
    }

    private init() {
        // Wire pipeline: UDP → FrameReceiver → VideoDecoder → MetalRenderer
        udpChannel.onReceive = { [weak self] data, endpoint in
            guard let self = self else { return }
            guard data.count >= ERDConstants.packetHeaderSize else { return }

            // Bypass frame assembly queue for zero-jitter, real-time audio playback.
            // Magic check first: spoofed datagrams must not reach any handler.
            guard data[0] == UInt8(truncatingIfNeeded: ERDConstants.magic),
                  data[1] == UInt8(ERDConstants.magic >> 8) else { return }
            if data[2] == PacketType.audioFrame.rawValue {
                if !self.isAudioMuted.value {
                    let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)
                    self.handleAudioPayload(payload)
                }
            } else {
                self.frameReceiver.handlePacket(data)
            }
        }

        frameReceiver.onFrameReady = { [weak self] data, header in
            self?.serverScreenWidth = Int(header.width)
            self?.serverScreenHeight = Int(header.height)
            self?.decoder.decode(data)
        }

        frameReceiver.onCursorUpdate = { [weak self] cursor in
            self?.renderer?.updateCursor(x: cursor.x, y: cursor.y)
        }

        decoder.onDecodedFrame = { [weak self] pixelBuffer in
            self?.renderer?.displayFrame(pixelBuffer)
        }
    }

    // MARK: - Connection Methods

    /// Connect via direct IP (LAN manual). Supply a previously granted
    /// pairing record, or a bootstrap PIN for first-time pairing; connecting
    /// with neither is refused.
    public func start(host: String?, pairing: PairingRecord?, bootstrapPIN: String?) {
        guard let host = host else { return }
        self.serverHost = host
        guard setTransportSecurity(pairing: pairing, bootstrapPIN: bootstrapPIN) else { return }
        ERDLog.info("[Client] Connecting to \(host)")

        tcpChannel.connect(host: host, port: ERDConstants.tcpPort)
        setupTCPHandlers(host: host)
    }

    public func start(host: String?) {
        start(host: host, pairing: PairingManager.shared.pairedDevices().first, bootstrapPIN: nil)
    }

    /// Connect via Bonjour endpoint
    public func start(endpoint: NWEndpoint, name: String, pairing: PairingRecord?, bootstrapPIN: String?) {
        ERDLog.info("[Client] Connecting to Bonjour Endpoint: \(name)")
        guard setTransportSecurity(pairing: pairing, bootstrapPIN: bootstrapPIN) else { return }
        tcpChannel.connect(to: endpoint)
        setupTCPHandlers(host: nil)
    }

    public func start(endpoint: NWEndpoint, name: String) {
        start(endpoint: endpoint, name: name, pairing: PairingManager.shared.pairedDevices().first, bootstrapPIN: nil)
    }

    @discardableResult
    private func setTransportSecurity(pairing: PairingRecord?, bootstrapPIN: String?) -> Bool {
        if let pairing {
            tcpChannel.security = .psk([PairingManager.shared.clientPSK(for: pairing)])
            activePairing = pairing
            return true
        }
        if let bootstrapPIN {
            tcpChannel.security = .psk([PairingManager.shared.clientPSK(pin: bootstrapPIN)])
            activePairing = nil
            return true
        }
        onError?("No paired device and no bootstrap PIN")
        return false
    }

    /// Connect via PIN (Internet / NAT traversal)
    public func startICE(pin: String) {
        Task {
            do {
                // 1. Get our public IP via STUN
                let stun = STUNClient()
                let (publicIP, publicPort) = try await stun.fetchPublicIP()
                ERDLog.info("[ClientCore] STUN Public IP: \(publicIP):\(publicPort)")

                // 2. Get local IP
                let localIP = NetworkUtils.getLocalIP() ?? "127.0.0.1"
                let localPort = ERDConstants.tcpPort

                // 3. Exchange candidates via ntfy.sh
                let signaling = SignalingClient(pin: pin, role: "client")
                let ourCandidate = SessionCandidate(role: "client", localIP: localIP, localPort: localPort,
                                                     publicIP: publicIP, publicPort: publicPort)

                ERDLog.info("[ClientCore] Waiting for server candidate via ntfy.sh...")
                let serverCandidate = try await signaling.exchangeCandidate(ourCandidate)
                ERDLog.info("[ClientCore] Retrieved Server Candidate: \(serverCandidate.publicIP):\(serverCandidate.publicPort)")
                signaling.stop()

                // 4. Try ICE: connect to both local and public IP
                var endpoints: [NWEndpoint] = []

                // Local IP endpoint
                if let port = NWEndpoint.Port(rawValue: serverCandidate.localPort) {
                    endpoints.append(.hostPort(host: NWEndpoint.Host(serverCandidate.localIP), port: port))
                }
                // Public IP endpoint
                if let port = NWEndpoint.Port(rawValue: serverCandidate.publicPort) {
                    endpoints.append(.hostPort(host: NWEndpoint.Host(serverCandidate.publicIP), port: port))
                }

                // Install handlers before dialing: the TLS channel can become
                // ready before connectICE returns.
                tcpChannel.security = .psk([PairingManager.shared.clientPSK(pin: pin)])
                setupTCPHandlers(host: nil)
                tcpChannel.connectICE(endpoints: endpoints)

            } catch {
                ERDLog.error("[ClientCore] ICE connection failed: \(error)")
                self.onError?("ICE connection failed: \(error.localizedDescription)")
            }
        }
    }

    public func stop() {
        stopClipboardSync()
        stopABR()
        stateQueue.sync {
            inputSender?.stopCapturing()
            inputSender = nil
            audioFragments.removeAll()
            sessionPairingKey = nil
            sessionSalt = Data()
            activePairing = nil
            renderer = nil
        }
        frameReceiver.stop()
        decoder.stop()
        audioPlayer.stop()
        serverHost = nil
        udpTargetHost = nil
        serverScreenWidth = 0
        serverScreenHeight = 0
        tcpChannel.stop()
        udpChannel.stop()
        ERDLog.info("[Client] Disconnected from server")
    }

    // MARK: - Internal

    private func setupTCPHandlers(host: String?) {
        tcpChannel.onConnect = { [weak self] in
            guard let self = self else { return }

            // Resolve server IP for UDP
            let resolvedHost = host ?? self.tcpChannel.remoteHostIP ?? "127.0.0.1"
            self.serverHost = resolvedHost
            self.udpTargetHost = resolvedHost

            if host == nil {
                ERDLog.info("[Client] Resolved server IP: \(resolvedHost)")
            }

            ERDLog.info("[Client] TLS channel established")
            if let pairing = self.activePairing {
                self.sendHandshake(with: pairing)
            } else {
                // Bootstrap channel: request pairing before any capability flows
                let request = PairingRequestPayload(hostname: ProcessInfo.processInfo.hostName)
                let header = PacketHeader(type: .pairingRequest, sequence: 0, timestamp: 0)
                var packet = header.serialize()
                packet.append(request.serialize())
                self.tcpChannel.send(packet)
            }
        }

        tcpChannel.onReceive = { [weak self] data in
            guard let self = self else { return }
            guard data.count >= ERDConstants.packetHeaderSize else {
                return
            }
            guard let header = PacketHeader.deserialize(from: data) else {
                return
            }
            let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

            if header.type == .pairingGrant {
                if let grant = PairingGrantPayload.deserialize(from: payload) {
                    let record = PairingRecord(id: grant.pairingID, name: grant.hostName, key: grant.key)
                    PairingManager.shared.adoptPairing(record)
                    self.activePairing = record
                    ERDLog.info("[Client] Paired with host \(grant.hostName)")
                    self.sendHandshake(with: record)
                }
            } else if header.type == .pairingReject {
                if let reject = PairingRejectPayload.deserialize(from: payload) {
                    ERDLog.warning("[Client] Pairing rejected: \(reject.reason)")
                    self.onError?("Pairing rejected")
                    self.stop()
                }
            } else if header.type == .handshakeAck {
                if let hs = HandshakePayload.deserialize(from: payload) {
                    guard hs.protocolVersion == ERDConstants.protocolVersion else {
                        ERDLog.warning("[Client] Host speaks protocol v\(hs.protocolVersion), expected v\(ERDConstants.protocolVersion)")
                        self.onError?("Protocol version mismatch")
                        self.stop()
                        return
                    }
                    ERDLog.info("[Client] Server: \(hs.hostname) \(hs.screenWidth)x\(hs.screenHeight) caps=\(hs.capabilities.rawValue)")
                    self.onServerIdentity?(hs.hostname)
                    self.serverScreenWidth = Int(hs.screenWidth)
                    self.serverScreenHeight = Int(hs.screenHeight)
                    self.stateQueue.sync { self.peerCapabilities = hs.capabilities }

                    if let key = self.sessionPairingKey, self.sessionSalt.count == 16 {
                        self.udpChannel.sendCipher = DatagramCipher.udpCipher(masterKey: key, sessionSalt: self.sessionSalt, clientToHost: true)
                        self.udpChannel.receiveCipher = DatagramCipher.udpCipher(masterKey: key, sessionSalt: self.sessionSalt, clientToHost: false)
                    }

                    let udpHost = self.udpTargetHost ?? self.serverHost ?? "127.0.0.1"
                    self.udpChannel.onReady = { [weak self] in
                        self?.udpChannel.sendPing()
                    }
                    self.udpChannel.connect(host: udpHost, port: ERDConstants.udpPort)
                    ERDLog.info("[Client] Connecting UDP to \(udpHost):\(ERDConstants.udpPort)")
                    self.startABR()
                    self.startClipboardSync()
                    self.audioPlayer.start()
                    self.onSessionReady?()
                }
            } else if header.type == .control {
                if let msg = ControlMessage.deserialize(from: payload) {
                    switch msg.type {
                    case .ping:
                        self.tcpChannel.sendControl(ControlMessage(type: .pong))
                    case .streamConfigResponse:
                        if let data = msg.payload,
                           let resp = StreamConfigurationResponsePayload.deserialize(from: data) {
                            ERDLog.info("[Client] Stream config accepted: \(resp.activeConfiguration.width)x\(resp.activeConfiguration.height)")
                            self.onStreamConfigResponse?(resp)
                        }
                    case .streamConfigReject:
                        if let data = msg.payload,
                           let reject = StreamConfigurationRejectPayload.deserialize(from: data) {
                            ERDLog.warning("[Client] Stream config rejected: \(reject.message)")
                            self.onStreamConfigRejected?(reject)
                        }
                    case .streamConfigError:
                        if let data = msg.payload,
                           let err = StreamConfigurationErrorPayload.deserialize(from: data) {
                            ERDLog.error("[Client] Stream config error: \(err.message)")
                            self.onStreamConfigError?(err)
                        }
                    case .clipboardSyncUpdate:
                        if let data = msg.payload,
                           let update = ClipboardSyncUpdatePayload.deserialize(from: data) {
                            self.handleClipboardUpdate(update)
                        }
                    case .clipboardSyncError:
                        if let data = msg.payload,
                           let err = ClipboardSyncErrorPayload.deserialize(from: data) {
                            ERDLog.warning("[Client] Clipboard sync error: \(err.message)")
                        }
                    default: break
                    }
                }
            }
        }

        tcpChannel.onDisconnect = { [weak self] in
            ERDLog.info("[Client] Disconnected from server")
            self?.onDisconnected?()
            self?.stop()
        }
    }

    public func setupRenderer(mtkView: MTKView) {
        renderer = MetalRenderer(mtkView: mtkView)
    }

    public func startInput(in view: NSView) {
        let sender = InputSender(tcpChannel: tcpChannel)
        sender.startCapturing(in: view)
        stateQueue.sync { inputSender = sender }
    }

    // MARK: - Session Security

    private func sendHandshake(with pairing: PairingRecord) {
        var salt = Data(count: 16)
        _ = salt.withUnsafeMutableBytes { SecRandomCopyBytes(kSecRandomDefault, 16, $0.baseAddress!) }
        stateQueue.sync {
            self.sessionSalt = salt
            self.sessionPairingKey = pairing.key
        }

        let hs = HandshakePayload(hostname: ProcessInfo.processInfo.hostName,
                                   screenWidth: 0, screenHeight: 0, scaleFactor: 1.0,
                                   capabilities: [.streamConfiguration, .textClipboardSync],
                                   pairingID: pairing.id,
                                   sessionSalt: salt)
        let header = PacketHeader(type: .handshake, sequence: 0, timestamp: 0)
        var packet = header.serialize()
        packet.append(hs.serialize())
        tcpChannel.send(packet)
        ERDLog.info("[Client] Handshake sent (paired as \(pairing.name))")
    }

    private func handleAudioPayload(_ payload: Data) {
        guard payload.count >= 8 else {
            audioPlayer.play(data: payload)
            return
        }
        let frameId = payload.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let index = payload.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let total = payload.subdata(in: 6..<8).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let chunk = payload.subdata(in: 8..<payload.count)

        guard total >= 1, index < total else { return }
        if total == 1 {
            audioPlayer.play(data: chunk)
            return
        }

        stateQueue.sync {
            if self.audioFragments.count > 64 { self.audioFragments.removeAll() }
            var entry = self.audioFragments[frameId] ?? (chunks: [:], total: total)
            entry.chunks[index] = chunk
            self.audioFragments[frameId] = entry

            if entry.chunks.count == Int(total) {
                self.audioFragments.removeValue(forKey: frameId)
                var assembled = Data()
                for i in 0..<total {
                    assembled.append(entry.chunks[i] ?? Data())
                }
                self.audioPlayer.play(data: assembled)
            }
        }
    }

    // MARK: - Stream Configuration

    public func requestStreamConfiguration(_ config: StreamConfiguration) {
        let requestID = stateQueue.sync { () -> UInt32 in
            let id = nextStreamConfigRequestID
            nextStreamConfigRequestID += 1
            return id
        }
        let request = StreamConfigurationRequestPayload(requestID: requestID, desiredConfiguration: config)
        let msg = ControlMessage(type: .streamConfigRequest, payload: request.serialize())
        tcpChannel.sendControl(msg)
        ERDLog.info("[Client] Requesting stream config: \(config.width)x\(config.height) @\(config.framesPerSecond)fps")
    }

    // MARK: - Clipboard Sync

    private func startClipboardSync() {
        let peerCaps = stateQueue.sync { self.peerCapabilities }
        guard peerCaps.contains(.textClipboardSync) else {
            ERDLog.info("[Client] Server does not support clipboard sync, skipping")
            return
        }

        let monitor = ClipboardMonitor { [weak self] text in
            guard let self = self else { return }
            let update = ClipboardSyncUpdatePayload(
                requestID: 0,
                direction: .clientToHost,
                origin: .localPasteboard,
                text: text)
            if let data = update.serialize() {
                let msg = ControlMessage(type: .clipboardSyncUpdate, payload: data)
                self.tcpChannel.sendControl(msg)
            }
        }
        stateQueue.sync { self.clipboardMonitor = monitor }
        monitor.start()
        ERDLog.info("[Client] Clipboard sync started")
    }

    private func stopClipboardSync() {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.stop()
        stateQueue.sync { self.clipboardMonitor = nil }
    }

    private func handleClipboardUpdate(_ update: ClipboardSyncUpdatePayload) {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.applyRemoteText(update.text)
        ERDLog.info("[Client] Clipboard received from server (\(update.text.count) chars)")
        onClipboardSynced?(update.text)
    }

    // MARK: - Adaptive Bitrate

    private func startABR() {
        stopABR()
        currentBitrate = ERDConstants.defaultBitrate
        lowLossStartTime = nil

        let timer = DispatchSource.makeTimerSource(queue: abrQueue)
        timer.schedule(deadline: .now() + 3.0, repeating: 3.0)
        timer.setEventHandler { [weak self] in
            self?.evaluateBitrate()
        }
        timer.resume()
        abrTimer = timer
    }

    private func stopABR() {
        abrTimer?.cancel()
        abrTimer = nil
    }

    private func evaluateBitrate() {
        let lossRatio = frameReceiver.frameLossRatio
        var newBitrate = currentBitrate

        if lossRatio > 0.10 {
            lowLossStartTime = nil
            newBitrate = max(ERDConstants.minBitrate, Int(Double(currentBitrate) * 0.75))
            ERDLog.info("[Client] ABR: loss \(String(format: "%.1f", lossRatio * 100))%% → reduce to \(newBitrate)")
        } else if lossRatio < 0.02 {
            if let start = lowLossStartTime {
                if Date().timeIntervalSince(start) >= 10.0 {
                    newBitrate = min(ERDConstants.maxBitrate, Int(Double(currentBitrate) * 1.10))
                    lowLossStartTime = Date()
                    ERDLog.info("[Client] ABR: stable → increase to \(newBitrate)")
                }
            } else {
                lowLossStartTime = Date()
            }
        } else {
            lowLossStartTime = nil
        }

        if newBitrate != currentBitrate {
            currentBitrate = newBitrate
            let payload = BitrateAdjustPayload(targetBitrate: Int32(newBitrate))
            let msg = ControlMessage(type: .bitrateAdjust, payload: payload.serialize())
            tcpChannel.sendControl(msg)
        }
    }

    public struct StreamStats {
        public let fps: Double
        public let bitrate: Int
        public let frameLoss: Double
        public let framesReceived: Int
    }

    public func getStats() -> StreamStats {
        StreamStats(
            fps: frameReceiver.recentFPS,
            bitrate: currentBitrate,
            frameLoss: frameReceiver.frameLossRatio,
            framesReceived: frameReceiver.totalFramesReceived
        )
    }
}

import AppKit

public class InputSender {
    private let tcpChannel: TCPChannel
    private var captureView: NSView?
    private var localMonitor: Any?

    public init(tcpChannel: TCPChannel) {
        self.tcpChannel = tcpChannel
    }

    deinit { stopCapturing() }

    public func startCapturing(in view: NSView) {
        self.captureView = view

        let eventMask: NSEvent.EventTypeMask = [
            .mouseMoved, .leftMouseDown, .leftMouseUp, .rightMouseDown, .rightMouseUp,
            .leftMouseDragged, .rightMouseDragged, .scrollWheel,
            .keyDown, .keyUp, .flagsChanged
        ]

        localMonitor = NSEvent.addLocalMonitorForEvents(matching: eventMask) { [weak self] event in
            self?.handleEvent(event)
            return event
        }
    }

    public func stopCapturing() {
        if let m = localMonitor {
            // NSEvent monitor removal must happen on the main thread; stop()
            // can be triggered from TCP callback queues during disconnect.
            if Thread.isMainThread {
                NSEvent.removeMonitor(m)
            } else {
                DispatchQueue.main.async { NSEvent.removeMonitor(m) }
            }
            localMonitor = nil
        }
        captureView = nil
    }

    private func handleEvent(_ event: NSEvent) {
        guard let view = captureView else { return }

        // Events landing on session overlay controls (buttons, pickers, text
        // fields) belong to this Mac, not the remote host.
        if let contentView = view.window?.contentView,
           let hit = contentView.hitTest(event.locationInWindow),
           hit !== view, !hit.isDescendant(of: view) {
            return
        }

        let location = view.convert(event.locationInWindow, from: nil)
        let bounds = view.bounds
        guard bounds.width > 0, bounds.height > 0 else { return }

        let normX = Float(max(0, min(1, location.x / bounds.width)))
        let normY = Float(max(0, min(1, 1.0 - (location.y / bounds.height)))) // Flip Y

        var inputType: InputEventType
        var keyCode: UInt16 = 0
        var scrollDX: Float = 0
        var scrollDY: Float = 0

        switch event.type {
        case .mouseMoved:       inputType = .mouseMove
        case .leftMouseDown:    inputType = .leftMouseDown
        case .leftMouseUp:      inputType = .leftMouseUp
        case .rightMouseDown:   inputType = .rightMouseDown
        case .rightMouseUp:     inputType = .rightMouseUp
        case .leftMouseDragged: inputType = .leftMouseDragged
        case .rightMouseDragged: inputType = .rightMouseDragged
        case .scrollWheel:
            inputType = .scrollWheel
            scrollDX = Float(event.scrollingDeltaX)
            scrollDY = Float(event.scrollingDeltaY)
        case .keyDown:
            inputType = .keyDown
            keyCode = event.keyCode
        case .keyUp:
            inputType = .keyUp
            keyCode = event.keyCode
        case .flagsChanged:
            inputType = .flagsChanged
            keyCode = event.keyCode
        default: return
        }

        // Map NSEvent modifier flags
        var modifiers = ModifierFlags()
        if event.modifierFlags.contains(.shift)   { modifiers.insert(.shift) }
        if event.modifierFlags.contains(.control) { modifiers.insert(.control) }
        if event.modifierFlags.contains(.option)  { modifiers.insert(.option) }
        if event.modifierFlags.contains(.command) { modifiers.insert(.command) }
        if event.modifierFlags.contains(.capsLock) { modifiers.insert(.capsLock) }

        let payload = InputEventPayload(type: inputType, x: normX, y: normY, keyCode: keyCode,
                                         modifiers: modifiers, scrollDeltaX: scrollDX, scrollDeltaY: scrollDY)
        tcpChannel.sendInput(payload)
    }
}

import Foundation
import os

public enum ERDLog {
    private static let subsystem = "com.indo.EclipticRD"

    private static let generalLog = OSLog(subsystem: subsystem, category: "general")
    private static let networkLog = OSLog(subsystem: subsystem, category: "network")
    private static let videoLog   = OSLog(subsystem: subsystem, category: "video")

    // Set ERD_CONSOLE_LOG=1 to mirror log lines to stdout (E2E runner uses this).
    private static func console(_ message: String) {
        if ProcessInfo.processInfo.environment["ERD_CONSOLE_LOG"] == "1" {
            print(message)
        }
    }

    public static func info(_ message: String) {
        console(message)
        os_log(.info, log: generalLog, "%{private}@", message)
    }

    public static func error(_ message: String) {
        console(message)
        os_log(.error, log: generalLog, "%{public}@", message)
    }

    public static func debug(_ message: String) {
        console(message)
        os_log(.debug, log: generalLog, "%{private}@", message)
    }

    public static func warning(_ message: String) {
        console(message)
        os_log(.default, log: generalLog, "%{public}@", message)
    }

    public static func network(_ message: String) {
        console(message)
        os_log(.info, log: networkLog, "%{private}@", message)
    }

    public static func video(_ message: String) {
        console(message)
        os_log(.info, log: videoLog, "%{public}@", message)
    }
}

import Foundation

public enum InputEventType: UInt8 {
    case mouseMove = 0
    case leftMouseDown = 1
    case leftMouseUp = 2
    case rightMouseDown = 3
    case rightMouseUp = 4
    case scrollWheel = 5
    case keyDown = 6
    case keyUp = 7
    case flagsChanged = 8
    case leftMouseDragged = 9
    case rightMouseDragged = 10
}

public struct ModifierFlags: OptionSet {
    public let rawValue: UInt16
    public init(rawValue: UInt16) { self.rawValue = rawValue }

    public static let shift   = ModifierFlags(rawValue: 1 << 0)
    public static let control = ModifierFlags(rawValue: 1 << 1)
    public static let option  = ModifierFlags(rawValue: 1 << 2)
    public static let command = ModifierFlags(rawValue: 1 << 3)
    public static let capsLock = ModifierFlags(rawValue: 1 << 4)
}

public struct InputEventPayload {
    public let type: InputEventType
    public let x: Float
    public let y: Float
    public let keyCode: UInt16
    public let modifiers: ModifierFlags
    public let scrollDeltaX: Float
    public let scrollDeltaY: Float

    public static let size = 21

    public init(type: InputEventType, x: Float, y: Float, keyCode: UInt16 = 0,
                modifiers: ModifierFlags = [], scrollDeltaX: Float = 0, scrollDeltaY: Float = 0) {
        self.type = type; self.x = x; self.y = y; self.keyCode = keyCode
        self.modifiers = modifiers; self.scrollDeltaX = scrollDeltaX; self.scrollDeltaY = scrollDeltaY
    }

    public func serialize() -> Data {
        var d = Data(capacity: InputEventPayload.size)
        var t = type.rawValue; d.append(Data(bytes: &t, count: 1))
        var fx = x.bitPattern.littleEndian; d.append(Data(bytes: &fx, count: 4))
        var fy = y.bitPattern.littleEndian; d.append(Data(bytes: &fy, count: 4))
        var kc = keyCode.littleEndian; d.append(Data(bytes: &kc, count: 2))
        var mf = modifiers.rawValue.littleEndian; d.append(Data(bytes: &mf, count: 2))
        var sdx = scrollDeltaX.bitPattern.littleEndian; d.append(Data(bytes: &sdx, count: 4))
        var sdy = scrollDeltaY.bitPattern.littleEndian; d.append(Data(bytes: &sdy, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> InputEventPayload? {
        guard data.count >= size else { return nil }
        guard let t = InputEventType(rawValue: data[0]) else { return nil }
        let x = Float(bitPattern: data.subdata(in: 1..<5).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let y = Float(bitPattern: data.subdata(in: 5..<9).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let kc = data.subdata(in: 9..<11).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let mf = ModifierFlags(rawValue: data.subdata(in: 11..<13).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        let sdx = Float(bitPattern: data.subdata(in: 13..<17).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let sdy = Float(bitPattern: data.subdata(in: 17..<21).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        return InputEventPayload(type: t, x: x, y: y, keyCode: kc, modifiers: mf, scrollDeltaX: sdx, scrollDeltaY: sdy)
    }
}

import Foundation

public class FrameReceiver {
    private struct FrameAssembly {
        let header: FrameHeaderPayload
        var chunks: [UInt16: Data]
        let startTime: Date

        var isComplete: Bool { chunks.count == Int(header.totalChunks) }

        func assemble() -> Data? {
            guard isComplete else { return nil }
            var result = Data(capacity: Int(header.totalSize))
            for i in 0..<header.totalChunks {
                guard let chunk = chunks[i] else { return nil }
                result.append(chunk)
            }
            return result
        }
    }

    private struct LossEntry {
        let timestamp: Date
        let lost: Int
        let total: Int
    }

    private var frames: [UInt32: FrameAssembly] = [:]
    // Chunks that arrived before their frame header under UDP reordering
    private var orphanChunks: [UInt32: [UInt16: Data]] = [:]
    private let assemblyQueue = DispatchQueue(label: "eclipticrd.frame-assembly", qos: .userInteractive)
    private var cleanupTimer: DispatchSourceTimer?
    private let timeout: Double = ERDConstants.frameAssemblyTimeout

    private var expectedFrameId: UInt32 = 0
    private var hasReceivedFirstFrame = false
    private var lossEntries: [LossEntry] = []
    private let lossLock = NSLock()

    private var completedFrameTimestamps: [Date] = []
    public private(set) var totalFramesReceived: Int = 0

    public var onFrameReady: ((Data, FrameHeaderPayload) -> Void)?
    public var onCursorUpdate: ((CursorUpdate) -> Void)?

    /// Computed property: FPS based on frames completed in the last 1 second
    public var recentFPS: Double {
        assemblyQueue.sync {
            let cutoff = Date().addingTimeInterval(-1.0)
            let recentCount = completedFrameTimestamps.filter { $0 > cutoff }.count
            return Double(recentCount)
        }
    }

    public var frameLossRatio: Double {
        lossLock.lock()
        defer { lossLock.unlock() }
        let cutoff = Date().addingTimeInterval(-5.0)
        let recent = lossEntries.filter { $0.timestamp > cutoff }
        let totalLost = recent.reduce(0) { $0 + $1.lost }
        let totalFrames = recent.reduce(0) { $0 + $1.total }
        guard totalFrames > 0 else { return 0.0 }
        return Double(totalLost) / Double(totalFrames)
    }

    public init() {
        startCleanupTimer()
    }

    deinit {
        let timer = cleanupTimer
        assemblyQueue.async {
            timer?.cancel()
        }
    }

    public func stop() {
        assemblyQueue.sync {
            self.frames.removeAll()
            self.orphanChunks.removeAll()
            self.completedFrameTimestamps.removeAll()
            self.totalFramesReceived = 0
            self.expectedFrameId = 0
        }
        lossLock.lock()
        lossEntries.removeAll()
        hasReceivedFirstFrame = false
        lossLock.unlock()
    }

    public func handlePacket(_ data: Data) {
        guard data.count >= ERDConstants.packetHeaderSize else { return }
        guard let header = PacketHeader.deserialize(from: data) else { return }
        let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

        assemblyQueue.async { [weak self] in
            switch header.type {
            case .frameHeader:
                self?.handleFrameHeader(payload)
            case .frameChunk:
                self?.handleFrameChunk(payload)
            case .cursorUpdate:
                if let cursor = CursorUpdate.deserialize(from: payload) {
                    self?.onCursorUpdate?(cursor)
                }
            default: break
            }
        }
    }

    private func handleFrameHeader(_ data: Data) {
        guard let fh = FrameHeaderPayload.deserialize(from: data) else {
            ERDLog.error("[FrameReceiver] Failed to deserialize frame header from \(data.count) bytes")
            return
        }

        if fh.isKeyFrame {
            let keysToRemove = frames.keys.filter { $0 < fh.frameId }
            for key in keysToRemove {
                if let assembly = frames[key], !assembly.isComplete {
                    frames.removeValue(forKey: key)
                }
            }
        }

        trackFrameLoss(receivedFrameId: fh.frameId)
        frames[fh.frameId] = FrameAssembly(header: fh, chunks: [:], startTime: Date())

        if let pending = orphanChunks.removeValue(forKey: fh.frameId) {
            for (index, data) in pending where index < fh.totalChunks {
                frames[fh.frameId]!.chunks[index] = data
            }
        }
    }

    private func handleFrameChunk(_ data: Data) {
        guard let chunk = FrameChunkPayload.deserialize(from: data) else {
            ERDLog.error("[FrameReceiver] Failed to deserialize chunk from \(data.count) bytes")
            return
        }

        if frames[chunk.frameId] != nil {
            let assembly = frames[chunk.frameId]!
            guard chunk.chunkIndex < assembly.header.totalChunks else { return }

            frames[chunk.frameId]!.chunks[chunk.chunkIndex] = chunk.chunkData
            let updated = frames[chunk.frameId]!

            if updated.isComplete {
                let completed = frames.removeValue(forKey: chunk.frameId)!
                if let frameData = completed.assemble() {
                    ERDLog.video("[FrameReceiver] ✅ Frame #\(chunk.frameId) assembled: \(frameData.count) bytes")
                    totalFramesReceived += 1
                    completedFrameTimestamps.append(Date())
                    let cutoff = Date().addingTimeInterval(-2.0)
                    completedFrameTimestamps.removeAll { $0 < cutoff }
                    onFrameReady?(frameData, completed.header)
                }
            }
            return
        }

        // No header yet: hold the chunk for reassembly when the header lands.
        guard orphanChunks.count < 16 else { return }
        var orphans = orphanChunks[chunk.frameId] ?? [:]
        guard orphans.count < Int(ERDConstants.maxChunksPerFrame) else {
            orphanChunks.removeValue(forKey: chunk.frameId)
            return
        }
        orphans[chunk.chunkIndex] = chunk.chunkData
        orphanChunks[chunk.frameId] = orphans
    }

    private func trackFrameLoss(receivedFrameId: UInt32) {
        lossLock.lock()
        defer { lossLock.unlock() }

        if !hasReceivedFirstFrame {
            hasReceivedFirstFrame = true
            expectedFrameId = receivedFrameId + 1
            lossEntries.append(LossEntry(timestamp: Date(), lost: 0, total: 1))
            return
        }

        let gap = receivedFrameId > expectedFrameId ? Int(receivedFrameId - expectedFrameId) : 0
        lossEntries.append(LossEntry(timestamp: Date(), lost: gap, total: 1 + gap))
        expectedFrameId = max(expectedFrameId, receivedFrameId &+ 1)

        let cutoff = Date().addingTimeInterval(-10.0)
        lossEntries.removeAll { $0.timestamp < cutoff }
    }

    private func startCleanupTimer() {
        let timer = DispatchSource.makeTimerSource(queue: assemblyQueue)
        timer.schedule(deadline: .now() + 1.0, repeating: 1.0)
        timer.setEventHandler { [weak self] in
            guard let self = self else { return }
            let now = Date()
            self.frames = self.frames.filter { now.timeIntervalSince($0.value.startTime) < self.timeout }
            self.orphanChunks.removeAll()
        }
        timer.resume()
        cleanupTimer = timer
    }
}

import Foundation
import AudioToolbox

public class ClientAudioPlayer {
    private var queue: AudioQueueRef?
    private let queueAccessQueue = DispatchQueue(label: "eclipticrd.audioplayer")
    private var isRunning = false
    private let format: AudioStreamBasicDescription

    public init() {
        // Configure ASBD for ScreenCaptureKit standard: 48kHz Stereo Float32 Interleaved
        var asbd = AudioStreamBasicDescription()
        asbd.mSampleRate = 48000.0
        asbd.mFormatID = kAudioFormatLinearPCM
        asbd.mFormatFlags = kAudioFormatFlagIsFloat | kAudioFormatFlagIsPacked
        asbd.mBytesPerPacket = 8 // 4 bytes (Float32) * 2 channels
        asbd.mFramesPerPacket = 1
        asbd.mBytesPerFrame = 8
        asbd.mChannelsPerFrame = 2
        asbd.mBitsPerChannel = 32
        self.format = asbd
    }

    deinit {
        stop()
    }

    public func start() {
        queueAccessQueue.sync {
            guard !isRunning else { return }

            var tempQueue: AudioQueueRef?
            var fmt = format
            // Create a low-latency playback output queue; buffers are freed
            // in the completion callback, so every enqueued buffer is released
            // exactly once after playback.
            let status = AudioQueueNewOutput(&fmt, { _, inQueue, inBuffer in
                AudioQueueFreeBuffer(inQueue, inBuffer)
            }, nil, nil, nil, 0, &tempQueue)

            guard status == noErr, let q = tempQueue else {
                ERDLog.error("[AudioPlayer] Failed to create AudioQueue: \(status)")
                return
            }

            self.queue = q
            AudioQueueStart(q, nil)
            self.isRunning = true
            ERDLog.info("[AudioPlayer] Started AudioQueue playback")
        }
    }

    public func stop() {
        queueAccessQueue.sync {
            guard isRunning, let q = queue else { return }
            AudioQueueStop(q, true)
            AudioQueueDispose(q, true)
            self.queue = nil
            self.isRunning = false
            ERDLog.info("[AudioPlayer] Stopped AudioQueue playback")
        }
    }

    public func play(data: Data) {
        queueAccessQueue.async { [weak self] in
            guard let self = self, self.isRunning, let q = self.queue else { return }

            // Garbage or spoofed datagrams must not reach the audio allocator
            guard !data.isEmpty, data.count <= 65_536 else { return }

            var buffer: AudioQueueBufferRef?
            let status = AudioQueueAllocateBuffer(q, UInt32(data.count), &buffer)

            guard status == noErr, let buf = buffer else { return }

            // Copy audio payload into native buffer
            data.withUnsafeBytes { rawBuffer in
                if let baseAddress = rawBuffer.baseAddress {
                    memcpy(buf.pointee.mAudioData, baseAddress, data.count)
                }
            }
            buf.pointee.mAudioDataByteSize = UInt32(data.count)

            // Enqueue buffer for immediate zero-latency audio playback
            AudioQueueEnqueueBuffer(q, buf, 0, nil)
        }
    }
}

import Foundation

public struct HandshakeCapabilities: OptionSet {
    public let rawValue: UInt64

    public init(rawValue: UInt64) {
        self.rawValue = rawValue
    }

    public static let streamConfiguration = HandshakeCapabilities(rawValue: 1 << 0)
    public static let clipboardSync = HandshakeCapabilities(rawValue: 1 << 1)
    public static let textClipboardSync = HandshakeCapabilities(rawValue: 1 << 2)
}

public struct HandshakePayload {
    public let hostname: String
    public let screenWidth: UInt16
    public let screenHeight: UInt16
    public let scaleFactor: Float
    public let protocolVersion: UInt8
    public let capabilities: HandshakeCapabilities
    public let pairingID: String
    public let sessionSalt: Data

    public init(hostname: String, screenWidth: UInt16, screenHeight: UInt16, scaleFactor: Float, protocolVersion: UInt8 = ERDConstants.protocolVersion, capabilities: HandshakeCapabilities = [], pairingID: String = "", sessionSalt: Data = Data()) {
        self.hostname = hostname
        self.screenWidth = screenWidth
        self.screenHeight = screenHeight
        self.scaleFactor = scaleFactor
        self.protocolVersion = protocolVersion
        self.capabilities = capabilities
        self.pairingID = pairingID
        self.sessionSalt = sessionSalt
    }

    public func serialize() -> Data {
        var data = Data()
        let nameData = hostname.data(using: .utf8) ?? Data()
        var nameLen = UInt16(nameData.count).littleEndian; data.append(Data(bytes: &nameLen, count: 2))
        data.append(nameData)
        var w = screenWidth.littleEndian; data.append(Data(bytes: &w, count: 2))
        var h = screenHeight.littleEndian; data.append(Data(bytes: &h, count: 2))
        var s = scaleFactor.bitPattern.littleEndian; data.append(Data(bytes: &s, count: 4))
        var version = protocolVersion; data.append(Data(bytes: &version, count: 1))
        var flags = capabilities.rawValue.littleEndian; data.append(Data(bytes: &flags, count: 8))
        let idData = Data(pairingID.utf8).prefix(256)
        var idLen = UInt16(idData.count).littleEndian; data.append(Data(bytes: &idLen, count: 2))
        data.append(idData)
        data.append(sessionSalt.prefix(16))
        return data
    }

    public static func deserialize(from data: Data) -> HandshakePayload? {
        guard data.count >= 2 else { return nil }
        var offset = 0
        let nameLen = Int(data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        offset += 2
        guard nameLen <= 1024, data.count >= offset + nameLen + 8 else { return nil }
        let hostname = String(data: data.subdata(in: offset..<offset+nameLen), encoding: .utf8) ?? ""
        offset += nameLen
        let w = data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }; offset += 2
        let h = data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }; offset += 2
        let sBits = data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let s = Float(bitPattern: sBits)
        offset += 4

        var protocolVersion = ERDConstants.legacyProtocolVersion
        var capabilities: HandshakeCapabilities = []
        var pairingID = ""
        var sessionSalt = Data()
        if data.count >= offset + 9 {
            protocolVersion = data[offset]
            let flags = data.subdata(in: (offset + 1)..<(offset + 9)).withUnsafeBytes { $0.load(as: UInt64.self).littleEndian }
            capabilities = HandshakeCapabilities(rawValue: flags)
            offset += 9
            if data.count >= offset + 2 {
                let idLen = Int(data.subdata(in: offset..<(offset + 2)).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
                offset += 2
                guard idLen <= 256, data.count >= offset + idLen else { return nil }
                pairingID = String(data: data.subdata(in: offset..<(offset + idLen)), encoding: .utf8) ?? ""
                offset += idLen
                if data.count >= offset + 16 {
                    sessionSalt = data.subdata(in: offset..<(offset + 16))
                }
            }
        }

        return HandshakePayload(hostname: hostname, screenWidth: w, screenHeight: h, scaleFactor: s, protocolVersion: protocolVersion, capabilities: capabilities, pairingID: pairingID, sessionSalt: sessionSalt)
    }
}

import Foundation

public enum PacketType: UInt8 {
    case handshake = 0
    case handshakeAck = 1
    case frameHeader = 2
    case frameChunk = 3
    case cursorUpdate = 4
    case inputEvent = 5
    case control = 6
    case ping = 7
    case audioFrame = 8
    case pairingRequest = 9
    case pairingGrant = 10
    case pairingReject = 11
}

public struct PacketHeader {
    public let magic: UInt16
    public let type: PacketType
    public let sequence: UInt32
    public let timestamp: UInt32
    public let flags: UInt8

    public init(type: PacketType, sequence: UInt32, timestamp: UInt32, flags: UInt8 = 0) {
        self.magic = ERDConstants.magic
        self.type = type
        self.sequence = sequence
        self.timestamp = timestamp
        self.flags = flags
    }

    public func serialize() -> Data {
        var data = Data(capacity: ERDConstants.packetHeaderSize)
        var m = magic.littleEndian; data.append(Data(bytes: &m, count: 2))
        var t = type.rawValue;      data.append(Data(bytes: &t, count: 1))
        var s = sequence.littleEndian; data.append(Data(bytes: &s, count: 4))
        var ts = timestamp.littleEndian; data.append(Data(bytes: &ts, count: 4))
        var f = flags;              data.append(Data(bytes: &f, count: 1))
        return data
    }

    public static func deserialize(from data: Data) -> PacketHeader? {
        guard data.count >= ERDConstants.packetHeaderSize else { return nil }
        let magic = data.subdata(in: 0..<2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        guard magic == ERDConstants.magic else { return nil }
        guard let type = PacketType(rawValue: data[2]) else { return nil }
        let seq = data.subdata(in: 3..<7).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let ts = data.subdata(in: 7..<11).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let flags = data[11]
        return PacketHeader(type: type, sequence: seq, timestamp: ts, flags: flags)
    }
}

import SwiftUI
import Network

@MainActor
final class ConnectionManager: ObservableObject {
    enum State {
        case disconnected
        case connecting
        case connected
        case error(String)
    }

    enum StreamQualityPreset: String, CaseIterable, Identifiable {
        case efficient
        case balanced
        case fluid

        var id: String { rawValue }

        var title: String {
            switch self {
            case .efficient: return "Efficient"
            case .balanced: return "Balanced"
            case .fluid: return "Fluid"
            }
        }

        var detail: String {
            switch self {
            case .efficient: return "4 Mbps · 30 fps"
            case .balanced: return "8 Mbps · 60 fps"
            case .fluid: return "12 Mbps · 90 fps"
            }
        }

        var bitrate: Int {
            switch self {
            case .efficient: return 4_000_000
            case .balanced: return ERDConstants.defaultBitrate
            case .fluid: return 12_000_000
            }
        }

        var framesPerSecond: Int {
            switch self {
            case .efficient: return 30
            case .balanced: return ERDConstants.defaultFPS
            case .fluid: return 90
            }
        }
    }

    enum StreamResolutionPreset: String, CaseIterable, Identifiable {
        case native
        case retina1440
        case desktop1080
        case compact720

        var id: String { rawValue }

        var title: String {
            switch self {
            case .native: return "Native"
            case .retina1440: return "1440p"
            case .desktop1080: return "1080p"
            case .compact720: return "720p"
            }
        }

        var detail: String {
            switch self {
            case .native: return "Match host display"
            case .retina1440: return "Sharp desktop fit"
            case .desktop1080: return "Balanced clarity"
            case .compact720: return "Bandwidth saver"
            }
        }

        func dimensions(for nativeWidth: Int, nativeHeight: Int) -> (width: Int, height: Int) {
            switch self {
            case .native:
                return Self.evenDimensions(width: nativeWidth, height: nativeHeight)
            case .retina1440:
                return Self.fittedDimensions(nativeWidth: nativeWidth, nativeHeight: nativeHeight, maxWidth: 2560, maxHeight: 1440)
            case .desktop1080:
                return Self.fittedDimensions(nativeWidth: nativeWidth, nativeHeight: nativeHeight, maxWidth: 1920, maxHeight: 1080)
            case .compact720:
                return Self.fittedDimensions(nativeWidth: nativeWidth, nativeHeight: nativeHeight, maxWidth: 1280, maxHeight: 720)
            }
        }

        private static func fittedDimensions(nativeWidth: Int, nativeHeight: Int, maxWidth: Int, maxHeight: Int) -> (width: Int, height: Int) {
            guard nativeWidth > 0, nativeHeight > 0 else {
                return evenDimensions(width: maxWidth, height: maxHeight)
            }

            let widthScale = CGFloat(maxWidth) / CGFloat(nativeWidth)
            let heightScale = CGFloat(maxHeight) / CGFloat(nativeHeight)
            let scale = min(widthScale, heightScale, 1)
            let fittedWidth = Int((CGFloat(nativeWidth) * scale).rounded(.down))
            let fittedHeight = Int((CGFloat(nativeHeight) * scale).rounded(.down))
            return evenDimensions(width: fittedWidth, height: fittedHeight)
        }

        private static func evenDimensions(width: Int, height: Int) -> (width: Int, height: Int) {
            let normalizedWidth = max(2, width - (width % 2))
            let normalizedHeight = max(2, height - (height % 2))
            return (normalizedWidth, normalizedHeight)
        }
    }

    enum SessionControlStatus {
        case ready
        case pending
        case applied
        case rejected
    }

    struct SessionControlState {
        var selectedQuality: StreamQualityPreset = .balanced
        var activeQuality: StreamQualityPreset = .balanced
        var selectedResolution: StreamResolutionPreset = .native
        var activeResolution: StreamResolutionPreset = .native
        var activeConfiguration: StreamConfiguration?
        var pendingConfiguration: StreamConfiguration?
        var isRequestPending = false
        var status: SessionControlStatus = .ready
        var statusTitle = "Session controls ready"
        var statusMessage = "The live stream is using the current host profile."
        var isImmersiveModeEnabled = false
        var isFullscreen = false

        var activeSummary: String {
            let resolutionLabel = activeResolution.title
            let qualityLabel = activeQuality.title
            return "\(resolutionLabel) · \(qualityLabel)"
        }
    }

    @Published var state: State = .disconnected
    @Published var serverName: String?
    @Published var sessionControls = SessionControlState()
    @Published var showClipboardToast = false
    @Published var clipboardToastText = ""
    @Published var isAudioMuted = false {
        didSet {
            ClientCore.shared.isAudioMuted.value = isAudioMuted
        }
    }
    @Published var hostStartError: String?
    @Published var pairingRequestHostName: String?
    private var pairingResponder: ((Bool) -> Void)?

    private var clipboardToastWorkItem: DispatchWorkItem?
    private var lastBonjourEndpoint: NWEndpoint?
    private var lastBonjourName: String?
    private var lastPIN: String?
    private var reconnectAttempts = 0
    private var expectingStop = false
    private var reconnectWorkItem: DispatchWorkItem?
    private var streamConfigTimeoutWorkItem: DispatchWorkItem?
    private let maxReconnectAttempts = 3
    private let streamConfigRequestTimeout: TimeInterval = 10

    init() {
        ClientCore.shared.onSessionReady = { [weak self] in
            Task { @MainActor [weak self] in
                guard let self else { return }
                self.reconnectAttempts = 0
                self.state = .connected
                self.resetSessionControlsForConnectedSession()
            }
        }
        ClientCore.shared.onServerIdentity = { [weak self] serverName in
            Task { @MainActor [weak self] in
                self?.serverName = serverName
            }
        }
        ClientCore.shared.onDisconnected = { [weak self] in
            Task { @MainActor [weak self] in
                guard let self else { return }
                self.sessionControls.isImmersiveModeEnabled = false
                self.sessionControls.isFullscreen = false
                self.cancelStreamConfigRequestTimeout()

                // A disconnect event that belongs to a stop() we issued is
                // stale bookkeeping; only unexpected drops may reconnect.
                if self.expectingStop {
                    self.expectingStop = false
                    return
                }
                self.attemptReconnect()
            }
        }
        ClientCore.shared.onError = { [weak self] message in
            Task { @MainActor [weak self] in
                self?.state = .error(message)
            }
        }
        ClientCore.shared.onStreamConfigResponse = { [weak self] response in
            Task { @MainActor [weak self] in
                self?.handleStreamConfigResponse(response)
            }
        }
        ClientCore.shared.onStreamConfigRejected = { [weak self] rejection in
            Task { @MainActor [weak self] in
                self?.handleStreamConfigRejection(rejection)
            }
        }
        ClientCore.shared.onStreamConfigError = { [weak self] error in
            Task { @MainActor [weak self] in
                self?.handleStreamConfigError(error)
            }
        }
        ClientCore.shared.onClipboardSynced = { [weak self] text in
            Task { @MainActor [weak self] in
                self?.triggerClipboardToast(text: text)
            }
        }
        ServerCore.shared.onStartFailed = { [weak self] message in
            Task { @MainActor [weak self] in
                self?.hostStartError = message
            }
        }
        ServerCore.shared.onPairingRequest = { [weak self] hostname, respond in
            Task { @MainActor [weak self] in
                guard let self else { respond(false); return }
                self.pairingResponder = respond
                self.pairingRequestHostName = hostname
            }
        }
    }

    func respondToPairingRequest(_ approved: Bool) {
        pairingResponder?(approved)
        pairingResponder = nil
        pairingRequestHostName = nil
    }

    func connectBonjour(endpoint: NWEndpoint, name: String) {
        cancelStreamConfigRequestTimeout()
        reconnectAttempts = 0
        state = .connecting
        serverName = name
        sessionControls = SessionControlState()
        lastBonjourEndpoint = endpoint
        lastBonjourName = name
        lastPIN = nil
        let pairing = PairingManager.shared.pairedDevices().first
        ClientCore.shared.start(endpoint: endpoint, name: name, pairing: pairing, bootstrapPIN: nil)
    }

    func connectPIN(pin: String) {
        cancelStreamConfigRequestTimeout()
        reconnectAttempts = 0
        state = .connecting
        sessionControls = SessionControlState()
        lastPIN = pin
        lastBonjourEndpoint = nil
        lastBonjourName = nil
        ClientCore.shared.startICE(pin: pin)
    }

    func disconnect() {
        reconnectWorkItem?.cancel()
        reconnectWorkItem = nil
        cancelStreamConfigRequestTimeout()
        expectingStop = true
        reconnectAttempts = 0
        sessionControls.isImmersiveModeEnabled = false
        sessionControls.isFullscreen = false
        ClientCore.shared.stop()
        state = .disconnected
        serverName = nil
        sessionControls = SessionControlState()
    }

    func retry() {
        reconnectAttempts = 0
        performReconnect()
    }

    func requestStreamConfiguration(quality: StreamQualityPreset? = nil, resolution: StreamResolutionPreset? = nil) {
        if let quality {
            sessionControls.selectedQuality = quality
        }

        if let resolution {
            sessionControls.selectedResolution = resolution
        }

        guard !sessionControls.isRequestPending else { return }
        guard let config = buildRequestedConfiguration() else {
            sessionControls.status = .ready
            sessionControls.statusTitle = "Waiting for host display"
            sessionControls.statusMessage = "Stream controls become active after the session reports the host resolution."
            return
        }

        sessionControls.pendingConfiguration = config
        sessionControls.isRequestPending = true
        sessionControls.status = .pending
        sessionControls.statusTitle = "Requesting stream update"
        sessionControls.statusMessage = "Asking the host for \(sessionControls.selectedResolution.title) at \(sessionControls.selectedQuality.detail)."

        ClientCore.shared.requestStreamConfiguration(config)
        scheduleStreamConfigRequestTimeout()
    }

    func setImmersiveModeEnabled(_ enabled: Bool) {
        sessionControls.isImmersiveModeEnabled = enabled
        if !enabled {
            sessionControls.isFullscreen = false
        }
    }

    func updateFullscreenState(_ isFullscreen: Bool) {
        sessionControls.isFullscreen = isFullscreen
        if !isFullscreen {
            sessionControls.isImmersiveModeEnabled = false
        }
    }

    private func attemptReconnect() {
        guard reconnectAttempts < maxReconnectAttempts else {
            state = .error("Connection lost after \(maxReconnectAttempts) retries")
            return
        }

        guard lastBonjourEndpoint != nil || lastPIN != nil else {
            cancelStreamConfigRequestTimeout()
            state = .disconnected
            serverName = nil
            sessionControls = SessionControlState()
            return
        }

        let delay = pow(2.0, Double(reconnectAttempts))
        reconnectAttempts += 1
        state = .connecting

        let work = DispatchWorkItem { [weak self] in
            self?.performReconnect()
        }
        reconnectWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: work)
    }

    private func performReconnect() {
        if let endpoint = lastBonjourEndpoint, let name = lastBonjourName {
            state = .connecting
            serverName = name
            cancelStreamConfigRequestTimeout()
            ClientCore.shared.start(endpoint: endpoint, name: name)
        } else if let pin = lastPIN {
            state = .connecting
            cancelStreamConfigRequestTimeout()
            ClientCore.shared.startICE(pin: pin)
        } else {
            state = .disconnected
        }
    }

    private func resetSessionControlsForConnectedSession() {
        let nativeWidth = ClientCore.shared.serverScreenWidth
        let nativeHeight = ClientCore.shared.serverScreenHeight
        let defaultConfiguration = StreamConfiguration(
            width: UInt32(max(2, nativeWidth)),
            height: UInt32(max(2, nativeHeight)),
            bitrate: UInt32(ERDConstants.defaultBitrate),
            framesPerSecond: UInt16(ERDConstants.defaultFPS)
        )

        sessionControls = SessionControlState(
            selectedQuality: .balanced,
            activeQuality: .balanced,
            selectedResolution: .native,
            activeResolution: .native,
            activeConfiguration: defaultConfiguration,
            pendingConfiguration: nil,
            isRequestPending: false,
            status: .ready,
            statusTitle: "Native stream live",
            statusMessage: "Use the floating controls to tune quality, resolution, or enter immersive mode.",
            isImmersiveModeEnabled: false,
            isFullscreen: false
        )
        cancelStreamConfigRequestTimeout()
    }

    private func buildRequestedConfiguration() -> StreamConfiguration? {
        let nativeWidth = ClientCore.shared.serverScreenWidth
        let nativeHeight = ClientCore.shared.serverScreenHeight

        guard nativeWidth > 0, nativeHeight > 0 else {
            return nil
        }

        let dimensions = sessionControls.selectedResolution.dimensions(for: nativeWidth, nativeHeight: nativeHeight)
        return StreamConfiguration(
            width: UInt32(dimensions.width),
            height: UInt32(dimensions.height),
            bitrate: UInt32(sessionControls.selectedQuality.bitrate),
            framesPerSecond: UInt16(sessionControls.selectedQuality.framesPerSecond)
        )
    }

    private func handleStreamConfigResponse(_ response: StreamConfigurationResponsePayload) {
        let activeConfiguration = response.activeConfiguration
        let nativeWidth = ClientCore.shared.serverScreenWidth
        let nativeHeight = ClientCore.shared.serverScreenHeight
        let matchedQuality = nearestQualityPreset(for: activeConfiguration)
        let matchedResolution = nearestResolutionPreset(for: activeConfiguration, nativeWidth: nativeWidth, nativeHeight: nativeHeight)

        sessionControls.activeConfiguration = activeConfiguration
        sessionControls.pendingConfiguration = nil
        sessionControls.isRequestPending = false
        cancelStreamConfigRequestTimeout()
        sessionControls.activeQuality = matchedQuality
        sessionControls.selectedQuality = matchedQuality
        sessionControls.activeResolution = matchedResolution
        sessionControls.selectedResolution = matchedResolution
        sessionControls.status = .applied
        sessionControls.statusTitle = "Stream profile applied"
        sessionControls.statusMessage = "Live at \(Int(activeConfiguration.width))×\(Int(activeConfiguration.height)) · \(Int(activeConfiguration.framesPerSecond)) fps · \(formatBitrate(Int(activeConfiguration.bitrate)))."
    }

    private func handleStreamConfigRejection(_ rejection: StreamConfigurationRejectPayload) {
        cancelStreamConfigRequestTimeout()
        sessionControls.pendingConfiguration = nil
        sessionControls.isRequestPending = false
        sessionControls.selectedQuality = sessionControls.activeQuality
        sessionControls.selectedResolution = sessionControls.activeResolution
        sessionControls.status = .rejected
        sessionControls.statusTitle = "Host kept current stream"
        sessionControls.statusMessage = rejection.message.isEmpty ? "The host rejected the requested stream profile." : rejection.message
    }

    private func handleStreamConfigError(_ error: StreamConfigurationErrorPayload) {
        cancelStreamConfigRequestTimeout()
        sessionControls.pendingConfiguration = nil
        sessionControls.isRequestPending = false
        sessionControls.selectedQuality = sessionControls.activeQuality
        sessionControls.selectedResolution = sessionControls.activeResolution
        sessionControls.status = .rejected
        sessionControls.statusTitle = "Stream update error"
        sessionControls.statusMessage = error.message.isEmpty ? "The host returned an error while applying the requested stream profile." : error.message
    }

    private func nearestQualityPreset(for configuration: StreamConfiguration) -> StreamQualityPreset {
        StreamQualityPreset.allCases.min { lhs, rhs in
            qualityDistance(from: lhs, to: configuration) < qualityDistance(from: rhs, to: configuration)
        } ?? .balanced
    }

    private func nearestResolutionPreset(for configuration: StreamConfiguration, nativeWidth: Int, nativeHeight: Int) -> StreamResolutionPreset {
        StreamResolutionPreset.allCases.min { lhs, rhs in
            resolutionDistance(from: lhs, to: configuration, nativeWidth: nativeWidth, nativeHeight: nativeHeight) < resolutionDistance(from: rhs, to: configuration, nativeWidth: nativeWidth, nativeHeight: nativeHeight)
        } ?? .native
    }

    private func qualityDistance(from preset: StreamQualityPreset, to configuration: StreamConfiguration) -> Int {
        abs(preset.bitrate - Int(configuration.bitrate)) + (abs(preset.framesPerSecond - Int(configuration.framesPerSecond)) * 100_000)
    }

    private func resolutionDistance(from preset: StreamResolutionPreset, to configuration: StreamConfiguration, nativeWidth: Int, nativeHeight: Int) -> Int {
        let dimensions = preset.dimensions(for: nativeWidth, nativeHeight: nativeHeight)
        return abs(dimensions.width - Int(configuration.width)) + abs(dimensions.height - Int(configuration.height))
    }

    private func formatBitrate(_ bitrate: Int) -> String {
        let mbps = Double(bitrate) / 1_000_000.0
        return String(format: "%.1f Mbps", mbps)
    }

    private func scheduleStreamConfigRequestTimeout() {
        streamConfigTimeoutWorkItem?.cancel()

        let workItem = DispatchWorkItem { [weak self] in
            guard let self, self.sessionControls.isRequestPending else { return }
            self.sessionControls.pendingConfiguration = nil
            self.sessionControls.isRequestPending = false
            self.sessionControls.selectedQuality = self.sessionControls.activeQuality
            self.sessionControls.selectedResolution = self.sessionControls.activeResolution
            self.sessionControls.status = .rejected
            self.sessionControls.statusTitle = "Stream update timed out"
            self.sessionControls.statusMessage = "The host did not respond in time. Please try again."
        }

        streamConfigTimeoutWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + streamConfigRequestTimeout, execute: workItem)
    }

    private func cancelStreamConfigRequestTimeout() {
        streamConfigTimeoutWorkItem?.cancel()
        streamConfigTimeoutWorkItem = nil
    }

    private func triggerClipboardToast(text: String) {
        clipboardToastWorkItem?.cancel()

        let preview = text.count > 15 ? String(text.prefix(12)) + "..." : text
        clipboardToastText = "Clipboard Synced: \"\(preview)\""
        showClipboardToast = true

        let work = DispatchWorkItem { [weak self] in
            withAnimation(.easeInOut(duration: 0.22)) {
                self?.showClipboardToast = false
            }
        }
        clipboardToastWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.5, execute: work)
    }
}

